export class AgentPluginEnablementService extends EnablementModel implements IAgentPluginEnablementService {
	declare readonly _serviceBrand: undefined;
	private readonly _identities;
	private readonly _copiedIdentities = new Map<string, string>();

	constructor(
		@IStorageService storageService: IStorageService,
		@IUserDataProfileService userDataProfileService: IUserDataProfileService,
	) {
		migrateCustomizationEnablementToApplicationStorage(storageService, userDataProfileService.currentProfile);
		super(AGENT_PLUGIN_ENABLEMENT_STORAGE_KEY, storageService);
		this._identities = this._register(observableMemento<ReadonlyMap<string, string>>({
			key: AGENT_PLUGIN_ENABLEMENT_IDENTITIES_STORAGE_KEY,
			defaultValue: new Map(),
			toStorage: value => JSON.stringify([...value]),
			fromStorage: value => new Map(JSON.parse(value)),
		})(StorageScope.APPLICATION, StorageTarget.MACHINE, storageService));
	}

	override readEnabled(key: string, reader?: IReader): ContributionEnablementState {
		return super.readEnabled(this._getIdentity(key, reader), reader);
	}

	override readProfileEnabled(key: string, reader?: IReader): boolean {
		return super.readProfileEnabled(this._getIdentity(key, reader), reader);
	}

	override setEnabled(key: string, state: ContributionEnablementState, tx?: ITransaction): void {
		super.setEnabled(this._getIdentity(key), state, tx);
	}

	override setDefaultEnabled(key: string, enabled: boolean, tx?: ITransaction): void {
		super.setDefaultEnabled(this._getIdentity(key), enabled, tx);
	}

	override remove(key: string): void {
		super.remove(this._getIdentity(key));
	}

	private _getIdentity(key: string, reader?: IReader): string {
		const identities = this._identities.read(reader);
		// Loaded installation identities also apply after switching to a profile without persisted aliases.
		const source = this._copiedIdentities.get(key) ?? key;
		return identities.get(key) ?? identities.get(source) ?? source;
	}

	copyEnablement(source: URI, target: URI): void {
		const sourceKey = source.toString();
		const targetKey = target.toString();
		const identities = new Map(this._identities.get());
		const identity = this._getIdentity(sourceKey);
		if (identity !== targetKey) {
			const sourceIdentity = this._copiedIdentities.get(sourceKey) ?? sourceKey;
			if (sourceIdentity !== targetKey) {
				this._copiedIdentities.set(targetKey, sourceIdentity);
			}
			identities.set(targetKey, identity);
		}
		this._identities.set(identities, undefined);
	}
}

export interface IDiscoveredAgentPlugins {
	readonly plugins: readonly IAgentPlugin[];
	readonly priority: AgentPluginDiscoveryPriority;
	readonly order: number;
}

interface IAgentPluginCandidate {
	readonly plugin: IAgentPlugin;
	readonly priority: AgentPluginDiscoveryPriority;
	readonly order: number;
	readonly pluginOrder: number;
	readonly canonicalKey: string;
}

/**
 * Path fragment that identifies a Copilot-CLI-installed plugin.
 */
const COPILOT_CLI_INSTALL_PATH_FRAGMENT = '/.copilot/installed-plugins/';

class AgentPluginPolicyEnablementModel implements IEnablementModel {
	constructor(
		private readonly base: IEnablementModel,
		private readonly policyEnablement?: IObservable<ReadonlyMap<string, boolean>>,
	) { }

	readEnabled(key: string, reader?: IReader): ContributionEnablementState {
		const policyValue = this.policyEnablement?.read(reader).get(key);
		return policyValue === true
			? ContributionEnablementState.EnabledProfile
			: policyValue === false
				? ContributionEnablementState.DisabledProfile
				: this.base.readEnabled(key, reader);
	}

	readProfileEnabled(key: string, reader?: IReader): boolean {
		return this.policyEnablement?.read(reader).get(key) ?? this.base.readProfileEnabled(key, reader);
	}

	canSetEnabled(key: string, state: ContributionEnablementState): boolean {
		return !this.policyEnablement?.get().has(key) && (this.base.canSetEnabled?.(key, state) ?? true);
	}

	setEnabled(key: string, state: ContributionEnablementState, tx?: ITransaction): void {
		if (!this.canSetEnabled(key, state)) {
			return;
		}
		this.base.setEnabled(key, state, tx);
	}

	setDefaultEnabled(key: string, enabled: boolean, tx?: ITransaction): void {
		this.base.setDefaultEnabled?.(key, enabled, tx);
	}

	remove(key: string): void {
		if (!this.policyEnablement?.get().has(key)) {
			this.base.remove(key);
		}
	}
}

export class AgentPluginCollisionEnablementModel extends CollisionEnablementModel {
	constructor(
		base: IEnablementModel,
		private readonly collisionGroups: IObservable<ReadonlyMap<string, readonly string[]>>,
		private readonly policyEnablement?: IObservable<ReadonlyMap<string, boolean>>,
	) {
		super(new AgentPluginPolicyEnablementModel(base, policyEnablement), collisionGroups);
	}

	override canSetEnabled(key: string, state: ContributionEnablementState): boolean {
		const group = isContributionEnabled(state) ? this.collisionGroups.get().get(key) : undefined;
		return super.canSetEnabled(key, state) && !group?.some(otherId => otherId !== key && this.policyEnablement?.get().get(otherId) === true);
	}

	override setEnabled(key: string, state: ContributionEnablementState, tx?: ITransaction): void {
		if (!this.canSetEnabled(key, state)) {
			return;
		}
		super.setEnabled(key, state, tx);
	}
}

export function getSortedAgentPlugins(discoveries: readonly IDiscoveredAgentPlugins[]): readonly IAgentPlugin[] {
	return getUniqueAgentPluginCandidates(discoveries)
		.map(candidate => candidate.plugin)
		.sort((a, b) => a.uri.toString().localeCompare(b.uri.toString()));
}
export function getCanonicalAgentPluginCollisionGroups(
	discoveries: readonly IDiscoveredAgentPlugins[],
	isBlocked?: (plugin: IAgentPlugin) => boolean,
	isForceEnabled?: (plugin: IAgentPlugin) => boolean,
): ReadonlyMap<string, readonly string[]> {
	const candidates = getUniqueAgentPluginCandidates(discoveries);
	const byCanonicalKey = new Map<string, { forced: string[]; others: string[] }>();
	for (const candidate of candidates) {
		if (isBlocked?.(candidate.plugin)) {
			continue;
		}
		let group = byCanonicalKey.get(candidate.canonicalKey);
		if (!group) {
			group = { forced: [], others: [] };
			byCanonicalKey.set(candidate.canonicalKey, group);
		}
		(isForceEnabled?.(candidate.plugin) ? group.forced : group.others).push(candidate.plugin.uri.toString());
	}

	const groups = new Map<string, readonly string[]>();
	for (const { forced, others } of byCanonicalKey.values()) {
		const group = [...forced, ...others];
		if (group.length < 2) {
			continue;
		}
		for (const key of group) {
			groups.set(key, group);
		}
	}
	return groups;
}

/**
 * Whether the `ChatEnabledPlugins` enterprise policy explicitly blocks this plugin.
 *
 * The policy is a **deny list**, not an allowlist: enterprise-managed `enabledPlugins` entries
 * add to (never replace) the plugins a user has installed. A plugin is blocked only when its
 * policy id is mapped to `false`; entries mapped to `true` enable the plugin, and a plugin the
 * policy never mentions is left to the user's own enablement. This keeps a customer's existing
 * plugins working when their enterprise deploys `enabledPlugins` for a different plugin.
 */
export function isAgentPluginBlockedByPolicy(
	plugin: IAgentPlugin,
	enabledPluginsPolicy: Record<string, boolean> | undefined,
): boolean {
	return getAgentPluginPolicyEnablement(plugin, enabledPluginsPolicy) === false;
}

export function isAgentPluginForceEnabledByPolicy(
	plugin: IAgentPlugin,
	enabledPluginsPolicy: Record<string, boolean> | undefined,
): boolean {
	return getAgentPluginPolicyEnablement(plugin, enabledPluginsPolicy) === true;
}

export function getAgentPluginPolicyEnablement(
	plugin: IAgentPlugin,
	enabledPluginsPolicy: Record<string, boolean> | undefined,
): boolean | undefined {
	const pluginId = getAgentPluginPolicyId(plugin);
	return pluginId === undefined ? undefined : enabledPluginsPolicy?.[pluginId];
}

export function getAgentPluginPolicyId(plugin: IAgentPlugin): string | undefined {
	const identity = getPolicyIdentity(plugin);
	return identity ? `${identity.name}@${identity.marketplace}` : undefined;
}

function getAgentPluginCandidates(discoveries: readonly IDiscoveredAgentPlugins[]): IAgentPluginCandidate[] {
	const candidates: IAgentPluginCandidate[] = [];
	for (const discovery of discoveries) {
		for (let pluginOrder = 0; pluginOrder < discovery.plugins.length; pluginOrder++) {
			const plugin = discovery.plugins[pluginOrder];
			candidates.push({
				plugin,
				priority: discovery.priority,
				order: discovery.order,
				pluginOrder,
				canonicalKey: getCanonicalPluginIdentity(plugin),
			});
		}
	}

	return candidates.sort((a, b) =>
		a.priority - b.priority
		|| a.order - b.order
		|| a.pluginOrder - b.pluginOrder
		|| a.plugin.uri.toString().localeCompare(b.plugin.uri.toString())
	);
}

function getUniqueAgentPluginCandidates(discoveries: readonly IDiscoveredAgentPlugins[]): IAgentPluginCandidate[] {
	const unique: IAgentPluginCandidate[] = [];
	const seen = new Set<string>();
	for (const candidate of getAgentPluginCandidates(discoveries)) {
		const key = candidate.plugin.uri.toString();
		if (seen.has(key)) {
			continue;
		}
		seen.add(key);
		unique.push(candidate);
	}
	return unique;
}

function getCanonicalPluginIdentity(plugin: IAgentPlugin): string {
	return getMarketplaceCanonicalIdentity(plugin.fromMarketplace)
		?? getCopilotCliInstallCanonicalIdentity(plugin)
		?? `uri:${plugin.uri.toString()}`;
}

function getMarketplaceCanonicalIdentity(plugin: IMarketplacePlugin | undefined): string | undefined {
	if (!plugin) {
		return undefined;
	}

	const normalizedName = normalizePluginIdentitySegment(plugin.name);
	const source = plugin.sourceDescriptor;
	switch (source.kind) {
		case PluginSourceKind.RelativePath: {
			if (plugin.marketplaceReference.githubRepo) {
				return `github:${plugin.marketplaceReference.githubRepo.toLowerCase()}|${normalizedName}`;
			}
			return `marketplace:${plugin.marketplaceReference.canonicalId}|${normalizedName}`;
		}
		case PluginSourceKind.GitHub: {
			const github = source as IGitHubPluginSource;
			return `github:${github.repo.toLowerCase()}|${normalizedName}`;
		}
		case PluginSourceKind.GitUrl: {
			const git = source as IGitUrlPluginSource;
			return `git:${git.url.toLowerCase()}|${normalizedName}`;
		}
		case PluginSourceKind.Npm: {
			const npm = source as INpmPluginSource;
			return `npm:${npm.package.toLowerCase()}|${normalizedName}`;
		}
		case PluginSourceKind.Pip: {
			const pip = source as IPipPluginSource;
			return `pip:${pip.package.toLowerCase()}|${normalizedName}`;
		}
	}
}

function getCopilotCliInstallCanonicalIdentity(plugin: IAgentPlugin): string | undefined {
	if (plugin.uri.scheme !== 'file') {
		return undefined;
	}

	const idx = plugin.uri.path.indexOf(COPILOT_CLI_INSTALL_PATH_FRAGMENT);
	if (idx === -1) {
		return undefined;
	}

	const segments = plugin.uri.path.slice(idx + COPILOT_CLI_INSTALL_PATH_FRAGMENT.length).split('/').filter(s => s.length > 0);
	if (segments.length !== 2) {
		return undefined;
	}

	const [bucket, installName] = segments;
	const normalizedName = normalizePluginIdentitySegment(plugin.label || installName);
	if (bucket !== '_direct') {
		return `copilot-cli-marketplace:${normalizePluginIdentitySegment(bucket)}|${normalizedName}`;
	}

	const match = /^(?<owner>.+)--(?<repo>.+)--(?<plugin>.+)$/.exec(installName);
	const groups = match?.groups;
	if (!groups) {
		return undefined;
	}

	return `github:${groups.owner.toLowerCase()}/${groups.repo.toLowerCase()}|${normalizePluginIdentitySegment(groups.plugin)}`;
}

function normalizePluginIdentitySegment(value: string): string {
	return value
		.trim()
		.toLowerCase()
		.replace(/\s+/g, '-')
		.replace(/[^a-z0-9_.:-]/g, '-')
		.replace(/-+/g, '-')
		.replace(/^[-:.]+|[-:.]+$/g, '');
}

interface IPolicyIdentity {
	readonly name: string;
	readonly marketplace: string;
	readonly marketplaceReference?: IMarketplaceReference;
}

function getPolicyIdentity(plugin: IAgentPlugin): IPolicyIdentity | undefined {
	const m = plugin.fromMarketplace;
	if (m) {
		return { name: m.name, marketplace: m.marketplace, marketplaceReference: m.marketplaceReference };
	}
	if (plugin.uri.scheme !== 'file') {
		return undefined;
	}
	const idx = plugin.uri.path.indexOf(COPILOT_CLI_INSTALL_PATH_FRAGMENT);
	if (idx === -1) {
		return undefined;
	}
	const segments = plugin.uri.path.slice(idx + COPILOT_CLI_INSTALL_PATH_FRAGMENT.length).split('/').filter(s => s.length > 0);
	if (segments.length !== 2) {
		return undefined;
	}
	const [marketplace, name] = segments;
	if (marketplace === '_direct') {
		return undefined;
	}
	return { name, marketplace };
}
