export interface IModelPickerPresentationOptions {
	readonly showManageModelsAction: boolean;
	readonly showUnavailableFeatured: boolean;
	readonly showAutoModel: boolean;
	readonly showModelIcon: boolean;
}

export interface IModelPickerDelegate {
	readonly comparison?: IModelPickerComparison;
	/** Whether a committed comparison is currently being submitted. */
	readonly comparisonBusy?: IObservable<boolean>;
	readonly currentModel: IObservable<ILanguageModelChatMetadataAndIdentifier | undefined>;
	setModel(model: ILanguageModelChatMetadataAndIdentifier): void;
	/**
	 * Moves focus to the prompt input that owns the picker. Called after a model
	 * comparison is completed, so the user can write the prompt next.
	 * When omitted, focus returns to where it was before the picker opened.
	 */
	focusInput?(): void;
	/**
	 * Shows the selection as an equivalent model without treating it as a user selection.
	 * Delegates whose {@link setModel} has no user-selection side effects may omit this; {@link setModel} is used instead.
	 */
	setModelProgrammatically?(model: ILanguageModelChatMetadataAndIdentifier): void;
	getModels(): ILanguageModelChatMetadataAndIdentifier[];
	/**
	 * Models offered while configuring a comparison. When omitted, comparisons
	 * use the same model pool as ordinary selection.
	 */
	getComparisonModels?(): ILanguageModelChatMetadataAndIdentifier[];
	getPresentationOptions(): IModelPickerPresentationOptions;
	/**
	 * The id of the current chat session, used to correlate model-picker
	 * changes with the session in telemetry. Matches the `chatSessionId`
	 * reported by other chat telemetry events (e.g. the chat request event).
	 * Returns `undefined` when no session is active.
	 */
	getChatSessionId?(): string | undefined;
	getAgentSessionId?(): string | undefined;
	getProvider?(): string | undefined;
	/**
	 * The session type (harness) the picker selects models for. Used to scope
	 * the Manage Models editor to that harness's Copilot models.
	 */
	getSessionType?(): string | undefined;
	/** The Agent Host connection the chat runs on, for its on-device models; when omitted, a local Copilot Agent Host chat assumes the local Agent Host. */
	getLocalModelConnection?(): IAgentConnection | undefined;
	/**
	 * UI hint flag controlling whether the picker shows the cache-break hint.
	 * Returns `true` when the session has likely warmed the prompt cache (e.g. it
	 * has sent a request), inferred from request history / session status rather
	 * than the provider's actual cache state — so it does not account for cache
	 * expiry or a cache that was already reset. Defaults to `false` when omitted.
	 */
	isCacheWarm?(): boolean;
	/**
	 * Per-editor model configuration access. When omitted, the picker reads and
	 * writes configuration through the global {@link ILanguageModelsService}.
	 */
	readonly modelConfiguration?: IModelConfigurationAccess;
}

/**
 * Action view item for selecting a language model in the chat interface.
 *
 * Wraps a {@link ModelPickerWidget} and adapts it for use in an action bar,
 * providing curated model suggestions, upgrade prompts, and provider tabs.
 */
export class ModelPickerActionItem extends BaseActionViewItem {
	private readonly _pickerWidget: ModelPickerWidget;
	private readonly _managedHover = this._register(new MutableDisposable());
	private _container: HTMLElement | undefined;
	private _minimumWidth: number | undefined;

	constructor(
		action: IAction,
		private readonly delegate: IModelPickerDelegate,
		private readonly pickerOptions: IChatInputPickerOptions,
		@IInstantiationService instantiationService: IInstantiationService,
		@IContextKeyService private readonly _contextKeyService: IContextKeyService,
		@IKeybindingService private readonly keybindingService: IKeybindingService,
	) {
		super(undefined, action);

		this._pickerWidget = this._register(instantiationService.createInstance(ModelPickerWidget, delegate));
		this._pickerWidget.setSelectedModel(delegate.currentModel.get());
		this._pickerWidget.setCompact(pickerOptions.compact);
		this._pickerWidget.setContextViewLayer(pickerOptions.contextViewLayer);
		if (pickerOptions.minimal) {
			this._pickerWidget.setMinimal(pickerOptions.minimal);
		}

		// Sync delegate → widget when model list or selection changes externally
		this._register(autorun(t => {
			const model = delegate.currentModel.read(t);
			this._pickerWidget.setSelectedModel(model);
			this._updateTooltip();
		}));

		// Sync widget → delegate when user picks a model
		this._register(this._pickerWidget.onDidChangeSelection(model => delegate.setModel(model)));
		this._register(this._pickerWidget.onDidChangeMinimumWidth(width => this._updateMinimumWidth(width)));
	}

	override render(container: HTMLElement): void {
		this._container = container;
		// Style the container before rendering, so the picker measures its name with
		// the sizes it will be laid out at.
		container.classList.add('chat-input-picker-item', 'model-picker-item');
		this._pickerWidget.render(container);
		this.element = this._pickerWidget.domNode;
		this._updateTooltip();
		this._updateMinimumWidth(this._pickerWidget.minimumWidth);
	}

	get minimumWidth(): number {
		return this._pickerWidget.minimumWidth;
	}

	private _updateMinimumWidth(width: number): void {
		if (!this._container || this._minimumWidth === width) {
			return;
		}
		this._minimumWidth = width;
		this._container.style.minWidth = `${width}px`;
	}

	private _getAnchorElement(): HTMLElement {
		if (this.element && getActiveWindow().document.contains(this.element)) {
			return this.element;
		}
		return this.pickerOptions.getOverflowAnchor?.() ?? this.element!;
	}

	public openModelPicker(): void {
		this._showPicker();
	}

	public show(anchor?: HTMLElement, options?: IModelPickerOpenOptions): void {
		this._pickerWidget.show(anchor ?? this._getAnchorElement(), false, false, undefined, options);
	}

	public getModelPickerControl(): { readonly element: HTMLElement; readonly open: (options: IModelPickerOpenOptions) => void; readonly select: (identifier: string) => boolean } | undefined {
		const element = this._pickerWidget.nameButton;
		return element && this._pickerWidget.canOpenWithFilter() ? {
			element,
			open: options => this.show(undefined, options),
			select: identifier => {
				const model = this.delegate.getModels().find(model => model.identifier === identifier && model.metadata.isUserSelectable !== false);
				if (!model || !this._pickerWidget.canOpenWithFilter()) {
					return false;
				}
				this.delegate.setModel(model);
				return true;
			},
		} : undefined;
	}

	public setEnabled(enabled: boolean): void {
		this._pickerWidget.setEnabled(enabled);
	}

	/**
	 * Whether the picker has no usable model because the workspace is untrusted
	 * (Restricted Mode). Lets a host (e.g. the sessions picker) keep the picker
	 * visible to surface the "Models" placeholder and Trust Workspace action
	 * instead of hiding it as an empty/no-model picker.
	 */
	public isRestrictedMode(): boolean {
		return this._pickerWidget.isRestrictedMode();
	}

	/**
	 * Whether the picker has no usable model because Chat still needs sign-in /
	 * setup. Like {@link isRestrictedMode}, lets a host keep the picker visible to
	 * surface the "Models" placeholder and Sign In action.
	 */
	public isSetupRequired(): boolean {
		return this._pickerWidget.isSetupRequired();
	}

	private _showPicker(): void {
		this._pickerWidget.show(this._getAnchorElement());
	}

	private _updateTooltip(): void {
		const target = this._pickerWidget.nameButton;
		if (!target) {
			return;
		}
		// Use a content factory so the hover reflects the current state each time
		// it is shown — in particular the Restricted Mode / sign-in messages, which
		// depend on workspace trust / entitlement changing without this item being
		// re-rendered.
		this._managedHover.value = getBaseLayerHoverDelegate().setupManagedHover(
			getDefaultHoverDelegate('mouse'),
			target,
			() => this._getHoverContents()
		);
	}

	private _getHoverContents(): IManagedHoverContent {
		// Keep the hover prefix in sync with the picker's visible "Models" label
		// (the same localization key) so the hover doesn't read "Pick Model • …".
		let label = localize('chat.modelPicker.modelsLabel', "Models");
		const keybindingLabel = this.keybindingService.lookupKeybinding(this._action.id, this._contextKeyService)?.getLabel();
		if (keybindingLabel) {
			label += ` (${keybindingLabel})`;
		}
		if (this._pickerWidget.isRestrictedMode()) {
			// Suffix avoids a leading "Models" so the hover doesn't stutter as
			// "Models • Models unavailable…" once the prefix is "Models".
			return this._appendComparisonAction(localize('chat.modelPicker.restrictedHover', "{0} • Unavailable while in Restricted mode. Trust Workspace to enable models.", label));
		}
		if (this._pickerWidget.isSetupRequired()) {
			return this._appendComparisonAction(localize('chat.modelPicker.setupRequiredHover', "{0} • Sign in to GitHub Copilot to choose a model.", label));
		}
		const comparisonSummary = this.delegate.comparison?.summary.get();
		if (comparisonSummary) {
			return this._appendComparisonAction(localize('chat.modelPicker.comparisonSummaryHover', "{0} • {1}", label, comparisonSummary));
		}
		const selectedModel = this._pickerWidget.selectedModel;
		const { statusIcon, tooltip } = selectedModel?.metadata || {};
		if (selectedModel) {
			label = localize('chat.modelPicker.selectedModelHover', "{0} • {1}", label, this._pickerWidget.fusionDisplayName ?? getLanguageModelDisplayNameWithSubscriptionSource(selectedModel));
		}
		if (statusIcon && tooltip) {
			label = localize('chat.modelPicker.selectedModelStatusHover', "{0} • {1}", label, tooltip);
		}
		const organizationDefaultDescription = this._pickerWidget.organizationDefaultDescription;
		const hover = organizationDefaultDescription
			? localize('chat.modelPicker.organizationDefaultHover', "{0}\n\n{1}", label, organizationDefaultDescription)
			: label;
		const fusionDescription = selectedModel?.metadata.autoModelFusion || this._pickerWidget.fusionDisplayName ? ILanguageModelChatMetadata.getAutoModelDescription(true) : undefined;
		if (!fusionDescription) {
			return this._appendComparisonAction(hover);
		}
		// Copilot Fusion's description carries a Learn more link, so it is rendered as Markdown.
		const comparisonAction = this._getComparisonAction();
		const markdown = new MarkdownString().appendMarkdown(escapeMarkdownSyntaxTokens(hover)).appendMarkdown('\n\n').appendMarkdown(fusionDescription);
		if (comparisonAction) {
			markdown.appendMarkdown('\n\n').appendMarkdown(escapeMarkdownSyntaxTokens(comparisonAction));
		}
		return {
			markdown,
			markdownNotSupportedFallback: this._appendComparisonAction(localize('chat.modelPicker.fusionHover', "{0}\n\n{1}", hover, ILanguageModelChatMetadata.getFusionSummary())),
		};
	}

	private _appendComparisonAction(hover: string): string {
		const action = this._getComparisonAction();
		return action ? localize('chat.modelPicker.comparisonActionHover', "{0}\n\n{1}", hover, action) : hover;
	}

	private _getComparisonAction(): string | undefined {
		const comparison = this.delegate.comparison;
		if (!comparison?.available.get() || !comparison.label) {
			return undefined;
		}
		const keybinding = comparison.startCommandId
			? this.keybindingService.lookupKeybinding(comparison.startCommandId, this._contextKeyService)?.getLabel()
			: undefined;
		const label = keybinding
			? localize('chat.modelPicker.comparisonActionWithKeybinding', "{0} ({1})", comparison.label, keybinding)
			: comparison.label;
		const description = comparison.description?.get();
		return description ? localize('chat.modelPicker.comparisonDescription', "{0}\n\n{1}", label, description) : label;
	}
}
