const AHP_CLIENT_CONNECTION_CLOSED = -32000;

function toAgentExtensionMode(value: unknown): AgentExtensionMode | undefined {
	if (typeof value !== 'string') {
		return undefined;
	}
	return value === 'disabled' || value === 'load_only' || value === 'load_and_augment' || value === 'unknown'
		? value
		: 'unknown';
}

function isAgentExtensionSource(value: unknown): value is AgentExtensionSource {
	return value === 'user' || value === 'project' || value === 'plugin';
}

function toAgentExtensionStatus(value: unknown): AgentExtensionStatus | undefined {
	if (typeof value !== 'string') {
		return undefined;
	}
	return value === 'running' || value === 'disabled' || value === 'failed' || value === 'starting' || value === 'unknown'
		? value
		: 'unknown';
}

/**
 * After this much inbound silence, send an application-level `ping` to
 * the remote so we have something to time out on. Reset on any inbound
 * data — busy connections don't generate ping traffic.
 *
 * Mirrors {@link ProtocolConstants.KeepAliveSendTime} from the regular
 * remote extension host stack.
 */
const PING_INTERVAL_MS = 5_000;

/**
 * Total inbound silence (ping interval + this) before a non-local connection
 * is declared dead and force-closed so the renderer's reconnect logic kicks
 * in. Reset on any inbound data. After a deferred close resumes, this
 * is also the full budget granted before the next liveness check.
 *
 * Matches {@link ProtocolConstants.TimeoutTime} from the regular remote
 * extension host stack.
 */
const LIVENESS_TIMEOUT_MS = 20_000;

function connectionTimeoutError(address: string, silenceMs: number): ProtocolError {
	return new ProtocolError(
		AHP_CLIENT_CONNECTION_CLOSED,
		`Connection appears dead: ${address}; no data received for ${silenceMs}ms.`,
	);
}

function connectionClosedError(address: string): ProtocolError {
	return new ProtocolError(AHP_CLIENT_CONNECTION_CLOSED, `Connection closed: ${address}`);
}

function connectionDisposedError(address: string): ProtocolError {
	return new ProtocolError(AHP_CLIENT_CONNECTION_CLOSED, `Connection disposed: ${address}`);
}

function transportLostError(address: string): ProtocolError {
	return new ProtocolError(AHP_CLIENT_CONNECTION_CLOSED, `Transport lost (reconnecting): ${address}`);
}

/**
 * Whether an error means the transport went away rather than the request
 * being rejected on its merits. Such a failure is transient and must stay
 * recoverable, so it is never reclassified as a terminal condition.
 */
function isConnectionClosedError(error: unknown): boolean {
	return error instanceof ProtocolError && error.code === AHP_CLIENT_CONNECTION_CLOSED;
}

