	/**
	 * List all sessions from the remote agent host.
	 */
	async listSessions(): Promise<(IAgentSessionMetadata & { readonly workingDirectory?: URI })[]> {
		const result = await this._sendRequest('listSessions', { channel: ROOT_STATE_URI });
		return result.items.map((hostSummary: SessionSummary) => {
			const s = this._withOlderHostDefaultChat(hostSummary.resource, hostSummary);
			const model = readCodexSessionModel(s);
			return {
				session: URI.parse(s.resource),
				provider: s.provider,
				startTime: Date.parse(s.createdAt),
				modifiedTime: Date.parse(s.modifiedAt),
				...(s.project ? {
					project: {
						uri: this._toClientUri(URI.parse(s.project.uri)),
						displayName: s.project.displayName,
					}
				} : {}),
				summary: s.title,
				status: s.status,
				activity: s.activity,
				workingDirectory: typeof s.workingDirectories?.[0] === 'string' ? this._toClientUri(URI.parse(s.workingDirectories[0])) : undefined,
				workingDirectories: s.workingDirectories?.map(d => this._toClientUri(URI.parse(d))),
				changes: s.changes,
				...(model ? { model } : {}),
				chats: s.chats?.map(chat => ({
					chat: URI.parse(chat.resource),
					summary: chat.title,
					kind: s.defaultChat === chat.resource ? 'default' : 'peer',
					origin: chat.origin,
					...(chat.interactivity !== undefined ? { interactivity: chat.interactivity } : {}),
					...(isSessionChatArchived(chat) ? { archived: true } : {}),
					...(chat.status !== undefined ? { status: chat.status, isRead: isSessionStatusRead(chat.status) } : {}),
					...(chat.changes !== undefined ? { changes: chat.changes } : {}),
				})) ?? (s.defaultChat ? [{ chat: URI.parse(s.defaultChat), kind: 'default' as const }] : undefined),
				// Carry durable host provenance for sessions first materialized from a listing.
				...(s._meta !== undefined ? { _meta: s._meta } : {}),
			};
		});
	}

	/**
	 * `value` with the default chat an older VS Code host did not advertise
	 * ({@link getOlderHostDefaultChat}). Every full session state and summary
	 * the host sends passes through here (subscribe, reconnect and restore
	 * snapshots, listings, `root/sessionAdded`), so the rest of the client
	 * reads `defaultChat` directly. A partial `root/sessionSummaryChanged`
	 * delta is not filled: an absent field there means unchanged. Returns a
	 * new object and never replaces an advertised value.
	 */
	private _withOlderHostDefaultChat<T extends Pick<SessionSummary, 'defaultChat'>>(session: string, value: T): T {
		if (value.defaultChat !== undefined) {
			return value;
		}
		const root = this.rootState.value;
		const defaultChat = getOlderHostDefaultChat(session, this._initializeResult.get(), root instanceof Error ? undefined : root);
		return defaultChat === undefined ? value : { ...value, defaultChat };
	}

	/** {@link _withOlderHostDefaultChat} for the session state of a snapshot; other snapshots pass through. */
	private _withOlderHostSnapshot(snapshot: IStateSnapshot): IStateSnapshot {
		const state = readSessionStateSnapshot(snapshot);
		const normalized = state ? this._withOlderHostDefaultChat(snapshot.resource, state) : undefined;
		if (normalized) {
			const operationId = generateUuid();
			this._onDidConnectionDiagnostic.fire({
				phase: 'session.snapshot', operationId, attemptId: this._diagnosticAttemptId,
				sessionResource: snapshot.resource, sessionState: normalized.lifecycle, timestamp: Date.now(), outcome: 'info',
			});
			const chats = new Set(normalized.chats.map(chat => chat.resource));
			if (normalized.defaultChat) {
				chats.add(normalized.defaultChat);
			}
			for (const chatResource of chats) {
				this._onDidConnectionDiagnostic.fire({
					phase: 'chat.binding', operationId, attemptId: this._diagnosticAttemptId,
					sessionResource: snapshot.resource, chatResource, timestamp: Date.now(), outcome: 'info',
				});
			}
		}
		return normalized ? { ...snapshot, state: normalized } : snapshot;
	}

	private _toClientUri(uri: URI): URI {
		return uri.scheme === Schemas.file ? toAgentHostUri(uri, this._connectionAuthority) : uri;
	}

	/**
	 * Inspect an outgoing client-dispatched action and grant implicit reads for
	 * resources that the host will need to read after receiving the action.
	 */
	private _grantImplicitReadsForOutgoingAction(action: SessionAction | ChatAction | TerminalAction | ClientChangesetAction | ClientAnnotationsAction | ClientAutomationAction | ClientAutomationRunAction | IRootConfigChangedAction): void {
		switch (action.type) {
			case ActionType.SessionActiveClientSet:
				if (action.activeClient.customizations) {
					this._grantImplicitReadsForCustomizations(action.activeClient.customizations);
				}
				break;
			case ActionType.ChatTurnStarted:
			case ActionType.ChatPendingMessageSet:
				this._grantImplicitReadsForMessage(action.message);
				break;
		}
	}

	private _grantImplicitReadsForMessage(message: Message): void {
		for (const attachment of message.attachments ?? []) {
			if (attachment.type !== MessageAttachmentKind.Resource) {
				continue;
			}
			try {
				this._grantImplicitRead(URI.parse(attachment.uri));
			} catch {
				continue;
			}
		}
	}

	/**
	 * Register implicit read grants for each customization URI that we are
	 * about to send to the host. The host needs to read these to materialize
	 * the customization, but should not need to write them. Grants are
	 * deduped per connection and revoked when the connection closes.
	 */
	private _grantImplicitReadsForCustomizations(refs: readonly ClientPluginCustomization[]): void {
		for (const ref of refs) {
			let uri: URI;
			try {
				uri = URI.parse(ref.uri);
			} catch {
				continue;
			}
			this._grantImplicitRead(uri);
		}
	}

	private _grantImplicitRead(uri: URI): void {
		if (this._grantedImplicitReadUris.has(uri)) {
			return;
		}
		this._grantedImplicitReadUris.add(uri);
		this._implicitReadGrants.add(this._resourceService.grantImplicitRead(this._resourceIdentity, uri));
	}

