export class ChatServiceTelemetry {
	constructor(
		@ITelemetryService private readonly telemetryService: ITelemetryService,
	) { }

	notifyUserAction(action: IChatUserActionEvent): void {
		const isAgentHostSession = getIsAgentHostSessionForTelemetry(action.sessionResource);
		if (action.action.kind === 'vote') {
			this.telemetryService.publicLog2<ChatVoteEvent, ChatVoteClassification>('interactiveSessionVote', {
				isAgentHostSession,
				direction: action.action.direction === ChatAgentVoteDirection.Up ? 'up' : 'down',
				agentId: action.agentId ?? '',
				command: action.command,
			});
		} else if (action.action.kind === 'copy') {
			this.telemetryService.publicLog2<ChatCopyEvent, ChatCopyClassification>('interactiveSessionCopy', {
				isAgentHostSession,
				copyKind: action.action.copyKind === ChatCopyKind.Action ? 'action' : 'toolbar',
				agentId: action.agentId ?? '',
				command: action.command,
			});
		} else if (action.action.kind === 'insert') {
			this.telemetryService.publicLog2<ChatInsertEvent, ChatInsertClassification>('interactiveSessionInsert', {
				isAgentHostSession,
				newFile: !!action.action.newFile,
				agentId: action.agentId ?? '',
				command: action.command,
			});
		} else if (action.action.kind === 'apply') {
			this.telemetryService.publicLog2<ChatApplyEvent, ChatApplyClassification>('interactiveSessionApply', {
				isAgentHostSession,
				newFile: !!action.action.newFile,
				codeMapper: action.action.codeMapper,
				agentId: action.agentId ?? '',
				command: action.command,
				editsProposed: !!action.action.editsProposed,
			});
		} else if (action.action.kind === 'runInTerminal') {
			this.telemetryService.publicLog2<ChatTerminalEvent, ChatTerminalClassification>('interactiveSessionRunInTerminal', {
				isAgentHostSession,
				languageId: action.action.languageId ?? '',
				agentId: action.agentId ?? '',
				command: action.command,
			});
		} else if (action.action.kind === 'followUp') {
			this.telemetryService.publicLog2<ChatFollowupEvent, ChatFollowupClassification>('chatFollowupClicked', {
				isAgentHostSession,
				agentId: action.agentId ?? '',
				command: action.command,
			});
		} else if (action.action.kind === 'chatEditingSessionAction') {
			this.telemetryService.publicLog2<ChatEditSessionEvent, ChatEditSessionClassification>('chatEditSession', {
				isAgentHostSession,
				agentId: action.agentId ?? '',
				outcome: action.action.outcome,
				hasRemainingEdits: action.action.hasRemainingEdits,
				requestId: action.requestId,
				modelId: escapeModelIdForTelemetry(action.modelId) ?? '',
				modeId: action.modeId ?? '',
			});
		} else if (action.action.kind === 'chatEditingHunkAction') {
			this.telemetryService.publicLog2<ChatEditHunkEvent, ChatEditHunkClassification>('chatEditHunk', {
				isAgentHostSession,
				agentId: action.agentId ?? '',
				outcome: action.action.outcome,
				lineCount: action.action.lineCount,
				hasRemainingEdits: action.action.hasRemainingEdits,
				requestId: action.requestId,
				modelId: escapeModelIdForTelemetry(action.modelId) ?? '',
				modeId: action.modeId ?? '',
			});
		}
	}

	retrievedFollowups(sessionResource: URI, agentId: string, command: string | undefined, numFollowups: number): void {
		this.telemetryService.publicLog2<ChatFollowupsRetrievedEvent, ChatFollowupsRetrievedClassification>('chatFollowupsRetrieved', {
			isAgentHostSession: getIsAgentHostSessionForTelemetry(sessionResource),
			agentId,
			command,
			numFollowups,
		});
	}
}

function getCodeBlocks(text: string): string[] {
	const lines = text.split('\n');
	const codeBlockLanguages: string[] = [];

	let codeBlockState: undefined | { readonly delimiter: string; readonly languageId: string };
	for (let i = 0; i < lines.length; i++) {
		const line = lines[i];

		if (codeBlockState) {
			if (new RegExp(`^\\s*${codeBlockState.delimiter}\\s*$`).test(line)) {
				codeBlockLanguages.push(codeBlockState.languageId);
				codeBlockState = undefined;
			}
		} else {
			const match = line.match(/^(\s*)(`{3,}|~{3,})(\w*)/);
			if (match) {
				codeBlockState = { delimiter: match[2], languageId: match[3] };
			}
		}
	}
	return codeBlockLanguages;
}

export class ChatRequestTelemetry {
	private isComplete = false;
	private readonly requestStartCopilotSku: string | undefined;
	private readonly selectedModelSource: ChatProviderInvokedEvent['selectedModelSource'];

	constructor(private readonly opts: {
		agent: IChatAgentData;
		agentSlashCommandPart: ChatRequestAgentSubcommandPart | undefined;
		commandPart: ChatRequestSlashCommandPart | undefined;
		requestIndex: number;
		sessionTypeSelectionReason: string | undefined;
		sessionResource: URI;
		location: ChatAgentLocation;
		options: IChatSendRequestOptions | undefined;
		enableCommandDetection: boolean;
		isVirtualWorkspace: boolean;
		settingDefaultToCopilotHarness: boolean;
		settingPreferCopilotHarness: boolean;
		settingLocalAgentEnabled: boolean;
		settingCopilotHarnessIntroductionMode: string;
	},
		@ITelemetryService private readonly telemetryService: ITelemetryService,
		@ILanguageModelsService private readonly languageModelsService: ILanguageModelsService,
		@IChatSessionsService private readonly chatSessionsService: IChatSessionsService,
		@IChatEntitlementService chatEntitlementService: IChatEntitlementService,
	) {
		this.requestStartCopilotSku = chatEntitlementService.sku;
		const selectedModel = opts.options?.userSelectedModelId;
		const metadata = selectedModel ? languageModelsService.lookupLanguageModel(selectedModel) : undefined;
		const modelProvider = metadata?.targetChatSessionType
			? getAgentHostProviderForTelemetry(metadata.targetChatSessionType, chatSessionsService)
			: undefined;
		this.selectedModelSource = !metadata ? 'unknown'
			: isByokModel(metadata) ? 'byok'
				: metadata.vendor === COPILOT_VENDOR_ID || isCopilotAgentHostProvider(modelProvider) ? 'copilot'
					: metadata.targetChatSessionType && (!modelProvider || modelProvider === 'unknown') ? 'unknown'
						: 'other';
	}

	complete({ timeToFirstProgress, totalTime, result, requestType, request, detectedAgent }: {
		timeToFirstProgress: number | undefined;
		totalTime: number | undefined;
		result: ChatProviderInvokedEvent['result'];
		requestType: ChatProviderInvokedEvent['requestType'];
		// Should rearrange so these 2 can be in the constructor
		request: ChatRequestModel;
		detectedAgent: IChatAgentData | undefined;
	}) {
		if (this.isComplete) {
			return;
		}

		this.isComplete = true;
		const agentId = detectedAgent?.id ?? this.opts.agent.id;
		const provider = getAgentHostProviderForTelemetry(getChatSessionType(this.opts.sessionResource), this.chatSessionsService);
		this.telemetryService.publicLog2<ChatProviderInvokedEvent, ChatProviderInvokedClassification>('interactiveSessionProviderInvoked', {
			provider,
			requestIndex: this.opts.requestIndex,
			sessionTypeSelectionReason: this.opts.sessionTypeSelectionReason,
			timeToFirstProgress,
			totalTime,
			result,
			requestType,
			requestId: request.id,
			agent: isRemoteAgentHostSessionType(agentId) ? 'remote-agent-host' : agentId,
			agentExtensionId: detectedAgent?.extensionId.value ?? this.opts.agent.extensionId.value,
			slashCommand: this.opts.agentSlashCommandPart ? this.opts.agentSlashCommandPart.command.name : this.opts.commandPart?.slashCommand.command,
			chatSessionId: getChatSessionIdForTelemetry(this.opts.sessionResource),
			enableCommandDetection: this.opts.enableCommandDetection,
			isParticipantDetected: !!detectedAgent,
			location: this.opts.location,
			citations: request.response?.codeCitations.length ?? 0,
			numCodeBlocks: getCodeBlocks(request.response?.response.toString() ?? '').length,
			attachmentKinds: this.attachmentKindsForTelemetry(request.variableData),
			model: this.resolveModelId(this.opts.options?.userSelectedModelId),
			requestStartCopilotSku: this.requestStartCopilotSku,
			selectedModelSource: this.selectedModelSource,
			permissionLevel: this.opts.options?.modeInfo?.kind === ChatModeKind.Ask ? undefined : this.opts.options?.modeInfo?.permissionLevel,
			chatMode: this.opts.options?.modeInfo?.telemetryModeName ?? this.opts.options?.modeInfo?.telemetryModeId,
			sessionType: getChatSessionTypeForTelemetry(this.opts.sessionResource),
			harness: isRemoteAgentHostSessionType(getChatSessionType(this.opts.sessionResource)) ? provider : undefined,
			isAgentHostSession: getIsAgentHostSessionForTelemetry(this.opts.sessionResource),
			isVirtualWorkspace: this.opts.isVirtualWorkspace,
			settingDefaultToCopilotHarness: this.opts.settingDefaultToCopilotHarness,
			settingPreferCopilotHarness: this.opts.settingPreferCopilotHarness,
			settingLocalAgentEnabled: this.opts.settingLocalAgentEnabled,
			settingCopilotHarnessIntroductionMode: this.opts.settingCopilotHarnessIntroductionMode,
		});
	}

	private attachmentKindsForTelemetry(variableData: IChatRequestVariableData): string[] {
		// this shows why attachments still have to be cleaned up somewhat
		return variableData.variables.map(v => {
			if (v.kind === 'implicit') {
				return 'implicit';
			} else if (v.range) {
				// 'range' is range within the prompt text
				if (v.kind === 'tool') {
					return 'toolInPrompt';
				} else if (v.kind === 'toolset') {
					return 'toolsetInPrompt';
				} else {
					return 'fileInPrompt';
				}
			} else if (v.kind === 'command') {
				return 'command';
			} else if (v.kind === 'symbol') {
				return 'symbol';
			} else if (isImageVariableEntry(v)) {
				return 'image';
			} else if (v.kind === 'directory') {
				return 'directory';
			} else if (v.kind === 'tool') {
				return 'tool';
			} else if (v.kind === 'toolset') {
				return 'toolset';
			} else {
				if (URI.isUri(v.value)) {
					return 'file';
				} else if (isLocation(v.value)) {
					return 'location';
				} else {
					return 'otherAttachment';
				}
			}
		});
	}

	private resolveModelId(userSelectedModelId: string | undefined): string | undefined {
		return userSelectedModelId && this.languageModelsService.lookupLanguageModel(userSelectedModelId)?.id;
	}
}

interface IChatSessionTelemetryContext {
	readonly chatSessionId: string;
	readonly sessionType: string;
	readonly harness: string | undefined;
}

/** Preserves workbench chat IDs while resolving the owning Agent Host session, without its connection authority. */
export function getChatSessionTelemetryIds(sessionResource: URI, connectionsService: Pick<IAgentHostConnectionsService, 'resolveSessionResourceIdentity'>): { chatSessionId: string; agentSessionId?: string } {
	const chatSessionId = getChatSessionIdForTelemetry(sessionResource);
	if (!isAgentHostSessionResource(sessionResource)) {
		return { chatSessionId };
	}
	const identity = connectionsService.resolveSessionResourceIdentity(sessionResource);
	if (!identity) {
		return { chatSessionId };
	}
	// Advertised backend resources are opaque; only a legacy fallback can be a provisional draft.
	const isProvisionalFallback = !identity.backendSessionIsAdvertised
		&& (isUntitledChatSession(sessionResource) || isUntitledChatSession(identity.backendSession));
	if (isProvisionalFallback) {
		return { chatSessionId };
	}
	return {
		chatSessionId,
		agentSessionId: AgentSession.id(identity.backendSession),
	};
}

/** Returns telemetry-safe session context, excluding remote Agent Host connection authorities. */
export function getChatSessionTelemetryContext(sessionResource: URI): IChatSessionTelemetryContext {
	return {
		chatSessionId: getChatSessionIdForTelemetry(sessionResource),
		sessionType: getChatSessionTypeForTelemetry(sessionResource),
		harness: getHarnessForTelemetry(sessionResource),
	};
}

function getChatSessionIdForTelemetry(sessionResource: URI): string {
	const sessionType = getChatSessionType(sessionResource);
	return isRemoteAgentHostSessionType(sessionType)
		? sessionResource.path.slice(1) + (sessionResource.fragment ? `#${sessionResource.fragment}` : '')
		: chatSessionResourceToId(sessionResource);
}

function getChatSessionTypeForTelemetry(sessionResource: URI): string {
	const sessionType = getChatSessionType(sessionResource);
	// Collapse the high-cardinality, host-specific authority into a single
	// value (the authority is PII); the harness is reported separately.
	return isRemoteAgentHostSessionType(sessionType) ? 'remote-agent-host' : sessionType;
}

function getIsAgentHostSessionForTelemetry(sessionResource: URI): boolean {
	return isAgentHostSessionResource(sessionResource);
}

/**
 * For remote agent host sessions, the underlying harness/provider so remote
 * activity can be split by harness (the collapsed sessionType cannot). See
 * telemetry gap #2 in #8209. Undefined for non-remote sessions.
 */
function getHarnessForTelemetry(sessionResource: URI): string | undefined {
	return parseRemoteAgentHostHarness(getChatSessionType(sessionResource));
}
