import { Color } from '../../../../base/common/color.js';
import { ColorIdentifier, editorBackground } from '../../../../platform/theme/common/colorRegistry.js';
import { registerThemingParticipant } from '../../../../platform/theme/common/themeService.js';
import { MODERN_EDITOR_TAB_ACTIVE_ACTION_BACKGROUND, MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, MODERN_EDITOR_TAB_ACTIVE_FOREGROUND, MODERN_EDITOR_TAB_ACTIVE_HOVER_ACTION_BACKGROUND, MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, MODERN_EDITOR_TAB_HOVER_ACTION_BACKGROUND, MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_EDITOR_TAB_HOVER_FOREGROUND, MODERN_EDITOR_TAB_INACTIVE_BACKGROUND, MODERN_EDITOR_TAB_SELECTED_ACTION_BACKGROUND, MODERN_TAB_ACTIVE_BACKGROUND, MODERN_TAB_ACTIVE_FOREGROUND, MODERN_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_FOREGROUND, TAB_ACTIVE_BACKGROUND, TAB_ACTIVE_BORDER, TAB_ACTIVE_BORDER_TOP, TAB_ACTIVE_FOREGROUND, TAB_BORDER, TAB_HOVER_BACKGROUND, TAB_HOVER_BORDER, TAB_HOVER_FOREGROUND, TAB_INACTIVE_BACKGROUND, TAB_INACTIVE_FOREGROUND, TAB_LAST_PINNED_BORDER, TAB_SELECTED_BORDER_TOP, TAB_UNFOCUSED_ACTIVE_BACKGROUND, TAB_UNFOCUSED_ACTIVE_BORDER, TAB_UNFOCUSED_ACTIVE_BORDER_TOP, TAB_UNFOCUSED_ACTIVE_FOREGROUND, TAB_UNFOCUSED_HOVER_BACKGROUND, TAB_UNFOCUSED_HOVER_BORDER, TAB_UNFOCUSED_HOVER_FOREGROUND, TAB_UNFOCUSED_INACTIVE_BACKGROUND, TAB_UNFOCUSED_INACTIVE_FOREGROUND } from '../../../common/theme.js';
import { ColorThemeData } from '../common/colorThemeData.js';

/**
 * Resolves the tab color to emit as a Modern UI variable, or `undefined` to leave the CSS default in place.
 *
 * When `relatedLegacyColorIds` are passed, `legacyColorId`'s default definition in the color registry is assumed
 * to derive from them (e.g. `tab.unfocusedInactiveForeground` derives transitively from `tab.inactiveForeground`
 * and `tab.activeForeground`), so customizing any related color flows through `getColor` into the derived value.
 */
function resolveLegacyTabColor(theme: ColorThemeData, legacyColorId: ColorIdentifier, modernColorIds: readonly ColorIdentifier[], ...relatedLegacyColorIds: ColorIdentifier[]): Color | undefined {
	if (modernColorIds.some(id => theme.getColorCustomization(id))) {
		return undefined;
	}
	if (!theme.getColorCustomization(legacyColorId) && !relatedLegacyColorIds.some(id => theme.getColorCustomization(id))) {
		return undefined;
	}
	return theme.getColor(legacyColorId);
}

function resolveExplicitTabColor(theme: ColorThemeData, modernColorId: ColorIdentifier, modernColorIds: readonly ColorIdentifier[], legacyColorId: ColorIdentifier, ...relatedLegacyColorIds: ColorIdentifier[]): Color | undefined {
	if (modernColorIds.some(id => theme.getColorCustomization(id))) {
		return theme.getColor(modernColorId);
	}
	return resolveLegacyTabColor(theme, legacyColorId, modernColorIds, ...relatedLegacyColorIds);
}

function addColorVariable(collector: (name: string, color: Color) => void, name: string, color: Color | undefined): void {
	if (color) {
		collector(name, color);
	}
}

function flattenTabBackground(color: Color, editorBackgroundColor: Color | undefined): Color {
	return editorBackgroundColor ? color.makeOpaque(editorBackgroundColor) : color;
}

function collectModernTabColorCustomizations(theme: ColorThemeData, collector: (name: string, color: Color) => void): void {
	const activeBackground = resolveLegacyTabColor(theme, TAB_ACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, MODERN_TAB_ACTIVE_BACKGROUND]);
	const unfocusedActiveBackground = resolveLegacyTabColor(theme, TAB_UNFOCUSED_ACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, MODERN_TAB_ACTIVE_BACKGROUND], TAB_ACTIVE_BACKGROUND);
	const inactiveBackground = resolveLegacyTabColor(theme, TAB_INACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_INACTIVE_BACKGROUND]);
	const unfocusedInactiveBackground = resolveLegacyTabColor(theme, TAB_UNFOCUSED_INACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_INACTIVE_BACKGROUND], TAB_INACTIVE_BACKGROUND);
	const hoverBackground = resolveLegacyTabColor(theme, TAB_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND]);
	const unfocusedHoverBackground = resolveLegacyTabColor(theme, TAB_UNFOCUSED_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND], TAB_HOVER_BACKGROUND);
	const activeHoverBackground = resolveLegacyTabColor(theme, TAB_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND]);
	const unfocusedActiveHoverBackground = resolveLegacyTabColor(theme, TAB_UNFOCUSED_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND], TAB_HOVER_BACKGROUND);
	const editorBackgroundColor = theme.getColor(editorBackground);
	const hasModernActiveActionBackground = theme.defines(MODERN_EDITOR_TAB_ACTIVE_ACTION_BACKGROUND);
	const hasModernHoverActionBackground = theme.defines(MODERN_EDITOR_TAB_HOVER_ACTION_BACKGROUND);
	const hasModernActiveHoverActionBackground = theme.defines(MODERN_EDITOR_TAB_ACTIVE_HOVER_ACTION_BACKGROUND);
	const explicitActiveActionBackground = hasModernActiveActionBackground ? theme.getColor(MODERN_EDITOR_TAB_ACTIVE_ACTION_BACKGROUND) : undefined;
	const explicitHoverActionBackground = hasModernHoverActionBackground ? theme.getColor(MODERN_EDITOR_TAB_HOVER_ACTION_BACKGROUND) : undefined;
	const explicitActiveHoverActionBackground = hasModernActiveHoverActionBackground ? theme.getColor(MODERN_EDITOR_TAB_ACTIVE_HOVER_ACTION_BACKGROUND) : undefined;
	const explicitSelectedActionBackground = theme.defines(MODERN_EDITOR_TAB_SELECTED_ACTION_BACKGROUND) ? theme.getColor(MODERN_EDITOR_TAB_SELECTED_ACTION_BACKGROUND) : undefined;
	const explicitActiveBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, MODERN_TAB_ACTIVE_BACKGROUND], TAB_ACTIVE_BACKGROUND);
	const explicitUnfocusedActiveBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_BACKGROUND, MODERN_TAB_ACTIVE_BACKGROUND], TAB_UNFOCUSED_ACTIVE_BACKGROUND, TAB_ACTIVE_BACKGROUND);
	const explicitInactiveBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_INACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_INACTIVE_BACKGROUND], TAB_INACTIVE_BACKGROUND);
	const explicitUnfocusedInactiveBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_INACTIVE_BACKGROUND, [MODERN_EDITOR_TAB_INACTIVE_BACKGROUND], TAB_UNFOCUSED_INACTIVE_BACKGROUND, TAB_INACTIVE_BACKGROUND);
	const explicitHoverBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND], TAB_HOVER_BACKGROUND);
	const explicitUnfocusedHoverBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND], TAB_UNFOCUSED_HOVER_BACKGROUND, TAB_HOVER_BACKGROUND);
	const explicitActiveHoverBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND], TAB_HOVER_BACKGROUND);
	const explicitUnfocusedActiveHoverBackground = resolveExplicitTabColor(theme, MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, [MODERN_EDITOR_TAB_ACTIVE_HOVER_BACKGROUND, MODERN_EDITOR_TAB_HOVER_BACKGROUND, MODERN_TAB_HOVER_BACKGROUND], TAB_UNFOCUSED_HOVER_BACKGROUND, TAB_HOVER_BACKGROUND);
	const tabBorder = resolveLegacyTabColor(theme, TAB_BORDER, []);
	const activeBorderTop = resolveLegacyTabColor(theme, TAB_ACTIVE_BORDER_TOP, []);
	const unfocusedActiveBorderTop = resolveLegacyTabColor(theme, TAB_UNFOCUSED_ACTIVE_BORDER_TOP, [], TAB_ACTIVE_BORDER_TOP);
	const selectedBorderTop = resolveLegacyTabColor(theme, TAB_SELECTED_BORDER_TOP, []);
	const explicitActiveBorderTop = theme.getColor(TAB_ACTIVE_BORDER_TOP) ? activeBorderTop : selectedBorderTop;
	const explicitUnfocusedActiveBorderTop = theme.getColor(TAB_UNFOCUSED_ACTIVE_BORDER_TOP) ? unfocusedActiveBorderTop : selectedBorderTop;

	addColorVariable(collector, '--modern-ui-editor-tab-active-background', activeBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-active-background', unfocusedActiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-inactive-background', inactiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-inactive-background', unfocusedInactiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-hover-background', hoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-hover-background', unfocusedHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-active-hover-background', activeHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-active-hover-background', unfocusedActiveHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-active-foreground', resolveLegacyTabColor(theme, TAB_ACTIVE_FOREGROUND, [MODERN_EDITOR_TAB_ACTIVE_FOREGROUND, MODERN_TAB_ACTIVE_FOREGROUND]));
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-active-foreground', resolveLegacyTabColor(theme, TAB_UNFOCUSED_ACTIVE_FOREGROUND, [MODERN_EDITOR_TAB_ACTIVE_FOREGROUND, MODERN_TAB_ACTIVE_FOREGROUND], TAB_ACTIVE_FOREGROUND));
	addColorVariable(collector, '--modern-ui-editor-tab-inactive-foreground', resolveLegacyTabColor(theme, TAB_INACTIVE_FOREGROUND, [], TAB_ACTIVE_FOREGROUND));
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-inactive-foreground', resolveLegacyTabColor(theme, TAB_UNFOCUSED_INACTIVE_FOREGROUND, [], TAB_INACTIVE_FOREGROUND, TAB_ACTIVE_FOREGROUND));
	addColorVariable(collector, '--modern-ui-editor-tab-hover-foreground', resolveLegacyTabColor(theme, TAB_HOVER_FOREGROUND, [MODERN_EDITOR_TAB_HOVER_FOREGROUND, MODERN_TAB_HOVER_FOREGROUND]));
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-hover-foreground', resolveLegacyTabColor(theme, TAB_UNFOCUSED_HOVER_FOREGROUND, [MODERN_EDITOR_TAB_HOVER_FOREGROUND, MODERN_TAB_HOVER_FOREGROUND], TAB_HOVER_FOREGROUND));
	addColorVariable(collector, '--modern-ui-editor-tab-border', tabBorder);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-border', tabBorder);
	addColorVariable(collector, '--modern-ui-editor-tab-last-pinned-border', resolveLegacyTabColor(theme, TAB_LAST_PINNED_BORDER, []));
	addColorVariable(collector, '--modern-ui-editor-tab-active-border', resolveLegacyTabColor(theme, TAB_ACTIVE_BORDER, []));
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-active-border', resolveLegacyTabColor(theme, TAB_UNFOCUSED_ACTIVE_BORDER, [], TAB_ACTIVE_BORDER));
	addColorVariable(collector, '--modern-ui-editor-tab-active-border-top', activeBorderTop);
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-active-border-top', unfocusedActiveBorderTop);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-active-border-top', explicitActiveBorderTop);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-unfocused-active-border-top', explicitUnfocusedActiveBorderTop);
	addColorVariable(collector, '--modern-ui-editor-tab-hover-border', resolveLegacyTabColor(theme, TAB_HOVER_BORDER, []));
	addColorVariable(collector, '--modern-ui-editor-tab-unfocused-hover-border', resolveLegacyTabColor(theme, TAB_UNFOCUSED_HOVER_BORDER, [], TAB_HOVER_BORDER));
	addColorVariable(collector, '--modern-ui-editor-tab-custom-active-background', explicitActiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-unfocused-active-background', explicitUnfocusedActiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-inactive-background', explicitInactiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-unfocused-inactive-background', explicitUnfocusedInactiveBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-hover-background', explicitHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-unfocused-hover-background', explicitUnfocusedHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-active-hover-background', explicitActiveHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-unfocused-active-hover-background', explicitUnfocusedActiveHoverBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-action-active-background', explicitActiveActionBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-action-hover-background', explicitHoverActionBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-action-active-hover-background', explicitActiveHoverActionBackground);
	addColorVariable(collector, '--modern-ui-editor-tab-custom-action-selected-background', explicitSelectedActionBackground);

	if (activeBackground && !hasModernActiveActionBackground) {
		addColorVariable(collector, '--modern-ui-editor-tab-action-active-background', flattenTabBackground(activeBackground, editorBackgroundColor));
	}
	if (unfocusedActiveBackground && !hasModernActiveActionBackground) {
		addColorVariable(collector, '--modern-ui-editor-tab-action-unfocused-active-background', flattenTabBackground(unfocusedActiveBackground, editorBackgroundColor));
	}
	if (hoverBackground && !hasModernHoverActionBackground) {
		addColorVariable(collector, '--modern-ui-editor-tab-action-hover-background', flattenTabBackground(hoverBackground, editorBackgroundColor));
	}
	if (unfocusedHoverBackground && !hasModernHoverActionBackground) {
		addColorVariable(collector, '--modern-ui-editor-tab-action-unfocused-hover-background', flattenTabBackground(unfocusedHoverBackground, editorBackgroundColor));
	}
	if (activeHoverBackground && !hasModernActiveHoverActionBackground) {
		addColorVariable(collector, '--modern-ui-editor-tab-action-active-hover-background', flattenTabBackground(activeHoverBackground, editorBackgroundColor));
	}
	if (unfocusedActiveHoverBackground && !hasModernActiveHoverActionBackground) {
		addColorVariable(collector, '--modern-ui-editor-tab-action-unfocused-active-hover-background', flattenTabBackground(unfocusedActiveHoverBackground, editorBackgroundColor));
	}
}

registerThemingParticipant((theme, collector) => {
	if (!(theme instanceof ColorThemeData)) {
		return;
	}
	const declarations: string[] = [];
	collectModernTabColorCustomizations(theme, (name, color) => declarations.push(`${name}: ${color};`));
	if (declarations.length > 0) {
		// The doubled `.monaco-workbench` raises specificity above the defaults in tabs.css so these overrides win regardless of style injection order.
		collector.addRule(`.modern-ui-tabs.monaco-workbench.monaco-workbench { ${declarations.join('\n')} }`);
	}
});
