/**
 * A pill rendered by {@link ChatPillsWidget}. The caller owns the action and any
 * state captured by the optional view-item factory.
 */
export interface IChatPill {
	readonly action: IAction;
	readonly createActionViewItem?: (options: IActionViewItemOptions) => IActionViewItem | undefined;
}

/** Observable data consumed by {@link ChatPillsWidget}. */
export interface IChatPillsModel {
	readonly pills: IObservable<readonly IChatPill[]>;
	readonly context?: IObservable<unknown>;
}

/** One entry a pill stands for. */
export interface IChatPillEntry {
	readonly id: string;
	readonly label: string;
	/** Optional metadata rendered after the dropdown row label by default. */
	readonly badge?: string;
	/** Places the badge before the label, keeping resource identity ahead of a resolving title. */
	readonly badgeBeforeLabel?: boolean;
	/** Keeps a resolved label stable until an open dropdown is dismissed. */
	readonly preserveLabelOnRefresh?: boolean;
	/** Optional CSS class added to the dropdown row. */
	readonly className?: string;
	/** Short label used when this entry renders as the pill itself. */
	readonly pillLabel?: string;
	readonly icon?: ThemeIcon;
	/** Renders the entry with its resource's themed file icon. */
	readonly resource?: URI;
	/** Displays a thumbnail above the resource location in the entry's hover. */
	readonly imagePreview?: {
		readonly resource: URI;
		readonly mimeType: string;
	};
	/** Actions shown at the trailing edge of the entry's dropdown row. */
	readonly toolbarActions?: readonly IChatPillAction[];
	/** Additional actions shown only in the rich hover footer. */
	readonly hoverActions?: readonly IChatPillAction[];
	/**
	 * Action shown on the entry's dropdown row alongside {@link toolbarActions},
	 * which consumers may also promote onto the pill itself when this is its
	 * only entry.
	 */
	readonly promotedAction?: IChatPillAction;
	/** Accessible name used when this entry is rendered as the pill itself. */
	readonly ariaLabel?: string;
	/** Accessible name for the dropdown row when it differs from the compact pill. */
	readonly dropdownAriaLabel?: string;
	/** Plain-text description of the content shown beside the dropdown entry. */
	readonly ariaDescription?: string;
	/** Content shown beside the entry while it is focused or hovered. */
	readonly hover?: IActionListItemHover;
	/** Tooltip for the pill when this is the only entry. */
	readonly tooltip?: string;
	/** Rich hover content for the pill when this is the only entry. */
	readonly pillHover?: IManagedHoverContent;
	/** Optional structured rendering when this entry is the only item. The entry's owner owns its lifetime. */
	readonly inlinePill?: IChatPill;
	/** Starts resolving metadata for this entry without opening it. */
	readonly prefetch?: () => void;
	open(): void;
}

export interface IChatPillAction extends IAction {
	/** Concise label used in the hover footer; the full label remains the row-action tooltip. */
	readonly hoverLabel?: string;
}

export type ChatReferenceKind = 'pullRequest' | 'issue';

export function getChatReferencePillPresentation(kind: ChatReferenceKind, reference: string, title?: string, fallbackTitle?: string) {
	const displayTitle = title || fallbackTitle;
	const typeLabel = kind === 'pullRequest'
		? localize('chatPills.pullRequest', "Pull Request")
		: localize('chatPills.issue', "Issue");
	const resourceLabel = displayTitle
		? localize('chatPills.referenceWithTitle', "{0} {1}: {2}", typeLabel, reference, displayTitle)
		: localize('chatPills.reference', "{0} {1}", typeLabel, reference);
	const dropdownAriaLabel = displayTitle
		? localize('chatPills.openReferenceWithTitle', "{0}, Open {1}: {2}", reference, typeLabel, displayTitle)
		: localize('chatPills.openReference', "{0}, Open {1}", reference, typeLabel);
	return {
		resourceLabel,
		entry: {
			label: displayTitle || typeLabel,
			badge: reference,
			badgeBeforeLabel: true,
			pillLabel: reference,
			className: 'chat-pill-reference',
			preserveLabelOnRefresh: title !== undefined,
			ariaLabel: localize('chatPills.openResource', "Open {0}", resourceLabel),
			dropdownAriaLabel,
		} satisfies Pick<IChatPillEntry, 'label' | 'badge' | 'badgeBeforeLabel' | 'pillLabel' | 'className' | 'preserveLabelOnRefresh' | 'ariaLabel' | 'dropdownAriaLabel'>,
	};
}

export const chatPillCopyUrlHoverLabel = localize('chatPills.copyUrl', "Copy URL");
export const chatPillCopyHashHoverLabel = localize('chatPills.copyHash', "Copy Hash");
export const chatPillRemoveReferenceHoverLabel = localize('chatPills.removeReference', "Remove Reference");
export const chatPillRemoveArtifactHoverLabel = localize('chatPills.removeArtifact', "Remove Artifact");

export function withChatPillHoverLabel<T extends IAction>(action: T, hoverLabel: string): T & IChatPillAction {
	return Object.assign(action, { hoverLabel });
}

export function getChatPillLocationHover(location: string): IActionListItemHover {
	const element = createChatPillHoverElement('chat-pill-location-hover', 'compact', 'content');
	element.textContent = location;
	return {
		content: element,
		contentOwnsPadding: true,
		panelClassName: 'chat-pill-hover-panel',
	};
}

export interface IChatPillImagePreview {
	readonly element: HTMLElement;
	readonly disposable: IDisposable;
}

const MAX_CHAT_PILL_IMAGE_PREVIEW_FILE_SIZE = 20 * 1024 * 1024;

/** Creates the visual preview shared by direct image pills and image rows in a dropdown. */
export function createChatPillImagePreview(entry: IChatPillEntry & { readonly imagePreview: NonNullable<IChatPillEntry['imagePreview']> }, fileService: IFileService, token = CancellationToken.None): IChatPillImagePreview {
	const preview = entry.imagePreview;
	const container = createChatPillHoverElement('chat-pill-image-preview');
	container.setAttribute('aria-busy', 'true');
	const disposables = new DisposableStore();
	const readToken = cancelOnDispose(disposables);
	disposables.add(token.onCancellationRequested(() => disposables.dispose()));
	if (token.isCancellationRequested) {
		disposables.dispose();
		return { element: container, disposable: disposables };
	}
	const showUnavailable = () => {
		if (disposables.isDisposed) {
			return;
		}
		container.setAttribute('aria-busy', 'false');
		container.replaceChildren(
			$('.chat-pill-image-preview-unavailable', undefined, localize('chatPills.imagePreviewUnavailable', "Image preview unavailable.")),
			$('.chat-image-hover-location', undefined, entry.ariaDescription ?? entry.tooltip ?? preview.resource.toString(true)),
		);
	};

	void fileService.readFile(preview.resource, { limits: { size: MAX_CHAT_PILL_IMAGE_PREVIEW_FILE_SIZE } }, readToken).then(content => {
		if (disposables.isDisposed) {
			return;
		}
		const imageHover = createChatImageHoverContent(
			preview.resource,
			entry.ariaDescription ?? entry.tooltip ?? preview.resource.toString(true),
			content.value.buffer,
			`${preview.resource.toString()}:${content.etag}`,
			() => {
				if (disposables.isDisposed) {
					return;
				}
				container.setAttribute('aria-busy', 'false');
				container.classList.add('loaded');
			},
			undefined,
			undefined,
			localize('chatPills.imagePreviewAlt', "Preview of {0}", entry.label),
			true,
			showUnavailable,
		);
		disposables.add(imageHover.disposable);
		container.replaceChildren(imageHover.element);
	}, () => {
		showUnavailable();
	});

	return { element: container, disposable: disposables };
}

/** Row actions for an entry: its {@link IChatPillEntry.toolbarActions} followed by any {@link IChatPillEntry.promotedAction}. */
export function getChatPillEntryToolbarActions(entry: IChatPillEntry): readonly IChatPillAction[] {
	const actions = [...entry.toolbarActions ?? []];
	if (entry.promotedAction && !actions.includes(entry.promotedAction)) {
		actions.push(entry.promotedAction);
	}
	return actions;
}

/** Footer actions for a rich entry hover, including row actions and hover-only actions. */
export function getChatPillEntryHoverActions(entry: IChatPillEntry): readonly IChatPillAction[] {
	const actions = [...entry.toolbarActions ?? [], ...entry.hoverActions ?? []];
	if (entry.promotedAction && !actions.includes(entry.promotedAction)) {
		actions.push(entry.promotedAction);
	}
	return actions;
}

export function getChatPillEntryHoverContents(entry: IChatPillEntry | undefined, fileService: IFileService, imageContents: WeakMap<IChatPillEntry, IManagedHoverContent>): IManagedHoverContent | undefined {
	if (!entry?.imagePreview) {
		return entry?.pillHover;
	}
	const imagePreview = entry.imagePreview;
	let content = imageContents.get(entry);
	if (!content) {
		content = {
			element: token => createChatPillImagePreview({ ...entry, imagePreview }, fileService, token).element,
			contentOwnsPadding: true,
		};
		imageContents.set(entry, content);
	}
	return content;
}

export function getChatPillEntryHoverOptions(entry: IChatPillEntry | undefined): IManagedHoverOptions | undefined {
	const actions = entry ? getChatPillEntryHoverActions(entry) : undefined;
	return actions?.length ? {
		trapFocus: true,
		actions: actions.map(action => ({
			commandId: action.id,
			label: action.hoverLabel ?? action.label,
			iconClass: action.class,
			run: () => { void action.run(); },
		})),
	} : undefined;
}

/** A titled group of entries, rendered as a dropdown section. */
export interface IChatPillSection {
	readonly title: string;
	readonly entries: readonly IChatPillEntry[];
}

/** Describes a pill entry's target while keeping its accessible name action-oriented. */
export function getChatPillResourceLocation(uri: URI, label: string, ariaLabel = localize('chatPills.open', "Open {0}", label)): Pick<IChatPillEntry, 'ariaDescription' | 'ariaLabel' | 'hover' | 'tooltip'> {
	const value = uri.toString(true);
	return {
		ariaDescription: value === label ? undefined : value,
		ariaLabel,
		hover: getChatPillLocationHover(value),
		tooltip: value,
	};
}

export function getChatPillEntries(sections: readonly IChatPillSection[]): readonly IChatPillEntry[] {
	return sections.flatMap(section => section.entries);
}

export interface IChatPillsWidgetOptions {
	readonly ariaLabel?: string;
	readonly actionRunner?: IActionRunner;
	/**
	 * Lets `contextmenu` bubble out of the pills. The toolbar otherwise swallows
	 * it per item, which would hide the pills from a surrounding context menu.
	 */
	readonly allowContextMenu?: boolean;
}

/**
 * The floating row's rendered height: 2px/4px vertical padding around a 22px
 * small button. Hosts reserve this much transcript space while the row is shown.
 */
export const CHAT_INPUT_PILLS_ROW_HEIGHT = 28;

export type ChatPillsCompactMode = boolean | 'auto';

export interface IChatPillsRowOptions {
	/** Collapses pills to icons; `auto` collapses only the trailing pills needed to fit, preserving accessible labels and tooltips. */
	readonly compact?: ChatPillsCompactMode;
	/** Window that owns the row. Required when rendering in an auxiliary window. */
	readonly targetWindow?: CodeWindow;
}

/** Shared horizontally scrollable row for pills mounted above a chat input. */
export class ChatPillsRow extends Disposable {

	readonly element: HTMLElement;
	readonly content: HTMLElement;

	private readonly _scrollable: DomScrollableElement;
	private readonly _resizeObserver: DisposableResizeObserver;
	private readonly _mutationObserver: MutationObserver | undefined;
	private _getPillElements: (() => readonly HTMLElement[]) | undefined;
	private _pillMeasurements: { readonly expandedWidth: number; readonly pills: readonly { readonly element: HTMLElement; readonly widthReduction: number }[] } | undefined;
	private _isLayouting = false;
	private readonly _onDidChangeLayout = this._register(new Emitter<void>());
	readonly onDidChangeLayout: Event<void> = this._onDidChangeLayout.event;
	private readonly _onDidRequestContextMenu = this._register(new Emitter<HTMLElement>());
	readonly onDidRequestContextMenu: Event<HTMLElement> = this._onDidRequestContextMenu.event;
	private readonly _pendingFocus = this._register(new MutableDisposable());

	constructor(debugName: string, options?: IChatPillsRowOptions) {
		super();

		const targetWindow = options?.targetWindow ?? mainWindow;
		this.content = $('.chat-pills-row-content');
		this._scrollable = this._register(new DomScrollableElement(this.content, {
			horizontal: ScrollbarVisibility.Auto,
			horizontalScrollbarSize: 6,
			scrollYToX: true,
			vertical: ScrollbarVisibility.Hidden,
			useShadows: false,
		}));
		this.element = this._scrollable.getDomNode();
		this.element.classList.add('chat-pills-row');
		const compactMode = options?.compact ?? false;
		this.element.classList.toggle('compact', compactMode === true);

		this._resizeObserver = this._register(new DisposableResizeObserver(debugName, entries => {
			if (entries.some(entry => entry.target !== this.content)) {
				this._pillMeasurements = undefined;
			}
			this.layout();
		}, targetWindow));
		this._register(this._resizeObserver.observe(this.content));
		if (compactMode === 'auto') {
			this._mutationObserver = new targetWindow.MutationObserver(() => {
				this._pillMeasurements = undefined;
				this.layout();
			});
			this._observeMutations();
			this._register({ dispose: () => this._mutationObserver?.disconnect() });
		} else {
			this._mutationObserver = undefined;
		}
		this._register(this._scrollable.onScroll(event => {
			this.element.classList.toggle('can-scroll-left', event.width > 0 && event.scrollLeft > 1);
			this.element.classList.toggle('can-scroll-right', event.width > 0 && event.scrollLeft + event.width < event.scrollWidth - 1);
			if (event.scrollLeftChanged) {
				this._onDidChangeLayout.fire();
			}
		}));
		this._register(addDisposableListener(this.content, EventType.SCROLL, () => this.scanDomNode()));
		this._register(addDisposableListener(this.content, EventType.FOCUS_IN, event => {
			if (isHTMLElement(event.target)) {
				event.target.scrollIntoView({ block: 'nearest', inline: 'nearest' });
			}
			this.scanDomNode();
		}));
		this._register(addDisposableListener(this.content, EventType.KEY_DOWN, event => {
			const keyboardEvent = new StandardKeyboardEvent(event);
			const target = isHTMLElement(event.target) ? event.target : this.content;
			const activatesEmptyRow = target === this.content && (keyboardEvent.keyCode === KeyCode.Enter || keyboardEvent.keyCode === KeyCode.Space);
			if (activatesEmptyRow
				|| keyboardEvent.keyCode === KeyCode.ContextMenu
				|| (keyboardEvent.shiftKey && keyboardEvent.keyCode === KeyCode.F10)) {
				EventHelper.stop(event, true);
				this._onDidRequestContextMenu.fire(target);
			}
		}));
	}

	/** Observes size changes; supplying the current pill buttons enables automatic compaction. */
	observe(element: HTMLElement, getPillElements?: () => readonly HTMLElement[]): void {
		this._register(this._resizeObserver.observe(element));
		if (getPillElements) {
			this._getPillElements = getPillElements;
		}
		this._pillMeasurements = undefined;
		this.layout();
	}

	layout(): void {
		if (this._isLayouting || !this.element.isConnected) {
			return;
		}

		this._isLayouting = true;
		if (this._mutationObserver?.takeRecords().length) {
			this._pillMeasurements = undefined;
		}
		this._mutationObserver?.disconnect();
		try {
			const availableWidth = this.element.clientWidth;
			if (this._mutationObserver && availableWidth > 0) {
				if (!this._pillMeasurements) {
					const pills = this._getPillElements?.() ?? [];
					for (const pill of pills) {
						pill.classList.remove('compact');
					}
					const expandedWidth = [...this.content.children].reduce((width, child) => {
						return isHTMLElement(child) ? Math.max(width, child.offsetLeft + child.offsetWidth) : width;
					}, 0);
					const expandedWidths = pills.map(pill => pill.getBoundingClientRect().width);
					for (const pill of pills) {
						pill.classList.add('compact');
					}
					this._pillMeasurements = {
						expandedWidth,
						pills: pills.map((element, index) => ({
							element,
							widthReduction: expandedWidths[index] - element.getBoundingClientRect().width,
						})),
					};
				}
				const { pills } = this._pillMeasurements;
				let requiredWidth = this._pillMeasurements.expandedWidth;
				let compactFrom = pills.length;
				while (compactFrom > 0 && requiredWidth > availableWidth + 1) {
					requiredWidth -= pills[--compactFrom].widthReduction;
				}
				for (let index = 0; index < pills.length; index++) {
					pills[index].element.classList.toggle('compact', index >= compactFrom);
				}
			}
			this.scanDomNode();
			this._onDidChangeLayout.fire();
		} finally {
			this._observeMutations();
			this._isLayouting = false;
		}
	}

	scanDomNode(): void {
		this._scrollable.scanDomNode();
	}

	private _observeMutations(): void {
		this._mutationObserver?.observe(this.content, {
			attributes: true,
			attributeFilter: ['class', 'hidden', 'style'],
			characterData: true,
			childList: true,
			subtree: true,
		});
	}

	setEmpty(empty: boolean, ariaLabel: string): void {
		this.element.classList.toggle('empty', empty);
		if (empty) {
			this.content.tabIndex = 0;
			this.content.setAttribute('role', 'button');
			this.content.setAttribute('aria-label', ariaLabel);
			this.content.setAttribute('aria-haspopup', 'menu');
		} else {
			this.content.removeAttribute('tabindex');
			this.content.removeAttribute('role');
			this.content.removeAttribute('aria-label');
			this.content.removeAttribute('aria-haspopup');
		}
	}

	restoreFocus(getPillElements: () => readonly HTMLElement[], fallback?: () => void): void {
		this._pendingFocus.value = disposableTimeout(() => {
			const pill = getPillElements().at(0);
			if (pill) {
				pill.focus();
			} else if (this.element.classList.contains('empty')) {
				this.content.focus();
			} else {
				fallback?.();
			}
		});
	}
}

/**
 * A reusable horizontal toolbar whose pill set and action context are observable.
 */
export class ChatPillsWidget extends Disposable {

	readonly element: HTMLElement;
	readonly isVisible: IObservable<boolean>;
	private readonly _onDidChangePills = this._register(new Emitter<void>());
	readonly onDidChangePills: Event<void> = this._onDidChangePills.event;
	private readonly _onDidRemoveFocusedPill = this._register(new Emitter<void>());
	readonly onDidRemoveFocusedPill: Event<void> = this._onDidRemoveFocusedPill.event;

	private readonly _toolbar: ChatPillsToolBar;
	private _pillByAction = new Map<IAction, IChatPill>();
	private _pills: readonly IChatPill[] = [];
	constructor(
		model: IChatPillsModel,
		options: IChatPillsWidgetOptions | undefined,
		@IContextMenuService contextMenuService: IContextMenuService,
	) {
		super();

		this.element = $('.chat-pills.hidden');
		this._toolbar = this._register(new ChatPillsToolBar(this.element, contextMenuService, {
			ariaLabel: options?.ariaLabel ?? localize('chatPills.ariaLabel', "Chat status"),
			actionRunner: options?.actionRunner,
			allowContextMenu: options?.allowContextMenu,
			actionViewItemProvider: (action, viewItemOptions) => {
				const viewItem = this._pillByAction.get(action)?.createActionViewItem?.(viewItemOptions) ?? new ChatPillActionViewItem(undefined, action, viewItemOptions);
				return viewItem;
			},
		}));

		this.isVisible = derived(this, reader => model.pills.read(reader).length > 0);
		this._register(autorun(reader => {
			const pills = model.pills.read(reader);
			this._pillByAction = new Map(pills.map(pill => [pill.action, pill]));
			this._toolbar.context = model.context?.read(reader);
			const pillsChanged = pills.length !== this._pills.length || pills.some((pill, index) => pill !== this._pills[index]);
			if (pillsChanged) {
				const focusedPill = this._pills.find((_pill, index) => {
					const viewItem = this._toolbar.getItemViewItem(index);
					return viewItem instanceof ChatPillActionViewItemBase && viewItem.isFocused();
				});
				const expandedPill = focusedPill ? undefined : this._pills.find((_pill, index) => {
					const viewItem = this._toolbar.getItemViewItem(index);
					return viewItem instanceof ChatPillActionViewItemBase && viewItem.buttonElement?.getAttribute('aria-expanded') === 'true';
				});
				const focusOwner = focusedPill ?? expandedPill;
				const focusedAction = focusOwner?.action;
				const focusedIndexBeforeUpdate = focusOwner ? this._pills.indexOf(focusOwner) : -1;
				const previousPills = this._pills;
				this._pills = pills;
				this._toolbar.setPills(previousPills, pills);
				const expandedPillPreserved = expandedPill && pills.includes(expandedPill);
				if (!expandedPillPreserved) {
					let focusedIndex = focusedAction ? pills.findIndex(pill => pill.action === focusedAction) : -1;
					if (focusedIndex < 0 && focusedIndexBeforeUpdate >= 0 && pills.length > 0) {
						focusedIndex = Math.min(focusedIndexBeforeUpdate, pills.length - 1);
					}
					if (focusedIndex >= 0) {
						this._toolbar.focus(focusedIndex);
					} else if (focusedIndexBeforeUpdate >= 0) {
						this._onDidRemoveFocusedPill.fire();
					}
				}
			}
			this.element.classList.toggle('hidden', pills.length === 0);
			if (pillsChanged) {
				this._onDidChangePills.fire();
			}
		}));
	}

	/** Returns the rendered button for each pill. */
	getPillElements(): readonly HTMLElement[] {
		const elements: HTMLElement[] = [];
		for (let index = 0; index < this._toolbar.getItemsLength(); index++) {
			const viewItem = this._toolbar.getItemViewItem(index);
			if (viewItem instanceof ChatPillActionViewItemBase && viewItem.buttonElement) {
				elements.push(viewItem.buttonElement);
			}
		}
		return elements;
	}

	focusFirst(): boolean {
		if (this._toolbar.getItemsLength() === 0) {
			return false;
		}
		this._toolbar.focus(0);
		return true;
	}

	/**
	 * The pill whose rendered item contains `target`, if any. Toolbar items are
	 * rendered in pill order, so their position identifies them without each
	 * pill having to tag its own DOM.
	 */
	getPill(target: HTMLElement | null | undefined): IChatPill | undefined {
		const item = target?.closest('.action-item');
		if (!item?.parentElement) {
			return undefined;
		}
		return this._pills[[...item.parentElement.children].indexOf(item)];
	}
}

/** Updates only the changed middle of a pill toolbar so stable pills keep their DOM and focus. */
class ChatPillsToolBar extends ToolBar {
	setPills(previous: readonly IChatPill[], next: readonly IChatPill[]): void {
		let prefix = 0;
		while (prefix < previous.length && prefix < next.length && previous[prefix] === next[prefix]) {
			prefix++;
		}

		let suffix = 0;
		while (suffix < previous.length - prefix
			&& suffix < next.length - prefix
			&& previous[previous.length - 1 - suffix] === next[next.length - 1 - suffix]) {
			suffix++;
		}

		for (let index = previous.length - suffix - 1; index >= prefix; index--) {
			this.actionBar.pull(index);
		}
		for (let index = prefix; index < next.length - suffix; index++) {
			this.actionBar.push(next[index].action, { icon: true, label: false, index });
		}
		let focusedIndex = -1;
		for (let index = 0; index < this.getItemsLength(); index++) {
			const viewItem = this.getItemViewItem(index);
			if (viewItem instanceof ChatPillActionViewItemBase && viewItem.isFocused()) {
				focusedIndex = index;
				break;
			}
		}
		let focusableSet = false;
		for (let index = 0; index < this.getItemsLength(); index++) {
			const viewItem = this.getItemViewItem(index);
			if (!(viewItem instanceof BaseActionViewItem)) {
				continue;
			}
			const focusable: boolean = focusedIndex >= 0 ? index === focusedIndex : !focusableSet && viewItem.isEnabled();
			viewItem.setFocusable(focusable);
			focusableSet ||= focusable;
		}
	}
}

/** Opaque base so a pill never shows the content it floats over; `chatPills.css` tints it. */
const chatPillBackground = asCssVariableWithDefault('chat.list.background', asCssVariable(buttonSecondaryBackground));

/** Creates a shared chat pill button. The caller owns its lifetime. */
export function createChatPillButton(container: HTMLElement, options?: { readonly supportIcons?: boolean }): Button {
	const button = new Button(container, {
		secondary: true,
		small: true,
		...options,
		...defaultButtonStyles,
		// Keep border sizing in CSS so joined segments can share edges without overriding inline styles.
		buttonSecondaryBorder: undefined,
		buttonSecondaryBackground: chatPillBackground,
		buttonSecondaryHoverBackground: chatPillBackground,
	});
	button.element.classList.add('monaco-text-button', 'chat-pill-button');
	return button;
}

/**
 * Shared plumbing for every chat pill: the button, click routing, enabled
 * state, and the roving-focus hooks the toolbar drives. Subclasses own only
 * what goes inside the button.
 */
export abstract class ChatPillActionViewItemBase extends BaseActionViewItem {

	protected button: Button | undefined;
	private _promotedAction: IChatPillAction | undefined;
	private _promotedActionElement: HTMLElement | undefined;

	/** The rendered button owned by this pill. */
	get buttonElement(): HTMLElement | undefined {
		return this.button?.element;
	}

	/**
	 * Per-pill modifier classes added alongside the shared `chat-pill-item` and
	 * `chat-pill-button`. A single class each, since these are applied with
	 * `classList.add`, which rejects space-separated values.
	 */
	protected get itemModifierClass(): string | undefined { return undefined; }
	protected get buttonModifierClass(): string | undefined { return undefined; }
	protected get buttonOptions(): { readonly supportIcons?: boolean } { return {}; }

	override render(container: HTMLElement): void {
		this.element = container;
		container.classList.add('chat-pill-item');
		if (this.itemModifierClass) {
			container.classList.add(this.itemModifierClass);
		}

		const button = this.button = this._register(createChatPillButton(container, this.buttonOptions));
		if (this.buttonModifierClass) {
			button.element.classList.add(this.buttonModifierClass);
		}
		// A click that dismisses this pill's own dropdown must not also re-open it.
		this._register(addDisposableListener(button.element.ownerDocument.body, EventType.MOUSE_DOWN, event => {
			if (event.button === 0 && (!isMacintosh || !event.ctrlKey) && this.hasOpenDropdown() && button.element.contains(event.target as Node | null)) {
				event.stopPropagation();
			}
		}));
		this._register(button.onDidClick(() => {
			if (this._action.enabled) {
				this.onDidClickButton();
			}
		}));

		this.renderContent(button);
		this.updateEnabled();
		this.updateTooltip();
	}

	/** Fills the button. Called once, after the button exists. */
	protected abstract renderContent(button: Button): void;

	protected hasOpenDropdown(): boolean {
		return false;
	}

	protected onDidClickButton(): void {
		this.actionRunner.run(this._action, this._context);
	}

	protected updatePromotedAction(action: IChatPillAction | undefined, icon: ThemeIcon | undefined, hoverService?: IHoverService): void {
		this._promotedAction = action;
		const container = this.element;
		if (!container) {
			return;
		}
		container.classList.toggle('has-promoted-action', !!action && !!icon);
		if (!action || !icon) {
			this._promotedActionElement?.remove();
			this._promotedActionElement = undefined;
			return;
		}
		const element = this._promotedActionElement ??= this._createPromotedActionElement(icon, hoverService);
		element.setAttribute('aria-label', action.label);
		if (element.parentElement !== container) {
			container.appendChild(element);
		}
	}

	private _createPromotedActionElement(icon: ThemeIcon, hoverService: IHoverService | undefined): HTMLElement {
		// Not a tab stop: the toolbar moves focus between whole pills, so keyboard
		// users take the action from the pill's context menu instead.
		const element = $(`span.chat-pill-promoted-action${ThemeIcon.asCSSSelector(icon)}`, { role: 'button', tabindex: '-1' });
		const hoverDelegate = this.options.hoverDelegate ?? getDefaultHoverDelegate('element');
		this._register(hoverService
			? hoverService.setupManagedHover(hoverDelegate, element, () => this._promotedAction?.tooltip || this._promotedAction?.label)
			: getBaseLayerHoverDelegate().setupManagedHover(hoverDelegate, element, () => this._promotedAction?.tooltip || this._promotedAction?.label));
		// Leave focus where it is, so a click that removes the pill cannot strand it.
		this._register(addDisposableListener(element, EventType.MOUSE_DOWN, event => event.preventDefault()));
		this._register(Gesture.addTarget(element));
		for (const eventType of [EventType.CLICK, TouchEventType.Tap]) {
			this._register(addDisposableListener(element, eventType, event => {
				EventHelper.stop(event, true);
				const action = this._promotedAction;
				if (action?.enabled) {
					Promise.resolve(action.run()).catch(onUnexpectedError);
				}
			}));
		}
		return element;
	}

	override focus(): void {
		if (this.button) {
			// Arrow navigation blurs the previous item, which drops it out of the
			// tab order; the newly focused item has to take its place or the row
			// ends up with no tab stop at all.
			this.button.element.tabIndex = 0;
			this.button.focus();
		}
	}

	override blur(): void {
		if (this.button) {
			this.button.element.tabIndex = -1;
			this.button.element.blur();
		}
	}

	override setFocusable(focusable: boolean): void {
		if (this.button) {
			this.button.element.tabIndex = focusable ? 0 : -1;
		}
	}

	override isFocused(): boolean {
		return !!this.button?.hasFocus();
	}

	protected override updateEnabled(): void {
		if (this.button) {
			this.button.enabled = this._action.enabled;
		}
	}

	protected override updateAriaLabel(): void {
		const ariaLabel = this.getAriaLabel();
		if (ariaLabel) {
			this.button?.element.setAttribute('aria-label', ariaLabel);
		} else {
			this.button?.element.removeAttribute('aria-label');
		}
	}

	protected getAriaLabel(): string | undefined {
		return this.getTooltip();
	}

	protected override getTooltip(): string | undefined {
		return this._action.tooltip || this._action.label || undefined;
	}
}

/** The default `icon + label` rendering for chat pill actions. */
export class ChatPillActionViewItem extends ChatPillActionViewItemBase {

	constructor(context: unknown, action: IAction, options: IActionViewItemOptions) {
		super(context, action, options);
	}

	protected override renderContent(): void {
		this.updateLabel();
	}

	protected override updateClass(): void {
		this.updateLabel();
	}

	protected override updateLabel(): void {
		if (this.button) {
			reset(this.button.element, ...this.getLabelContent());
		}
	}

	private getLabelContent(): Array<HTMLElement | string> {
		const content: Array<HTMLElement | string> = [];
		const iconElement = this.getIconElement();
		if (iconElement) {
			content.push(iconElement);
		}

		const labelText = this.getLabelText();
		if (labelText) {
			content.push($('span.chat-pill-label', undefined, labelText));
		}

		content.push(...this.getAdditionalLabelContent());
		return content;
	}

	protected getIconElement(): HTMLElement | undefined {
		const iconClasses = this._action.class?.split(' ').filter(cssClass => !!cssClass);
		if (!iconClasses?.length) {
			return undefined;
		}
		return $(`span.chat-pill-icon${iconClasses.map(cssClass => `.${cssClass}`).join('')}`, { 'aria-hidden': 'true' });
	}

	protected getLabelText(): string {
		return this._action.label;
	}

	protected getAdditionalLabelContent(): Array<HTMLElement | string> {
		return [];
	}
}
