		content.push(localize('chat.artifactActionDisclosure', "Artifact actions appear as collapsed request cards with an action and resource label. Use Tab to reach the card and Enter or Space to expand it. The details are a snapshot from when the action started. Use arrow keys within a details list and Enter to open an item. Agent Message switches between these details and the full prompt. Open the accessible view{0} while the request is focused to read its snapshot as text.", '<keybinding:editor.action.accessibleView>'));
