export interface ISessionTypeItem {
	type: AgentSessionTarget;
	label: string;
	hoverDescription: string;
	commandId: string;
}

const firstPartyCategory = { label: localize('chat.sessionTarget.category.agent', "Agent Types"), order: 1 };
const otherCategory = { label: localize('chat.sessionTarget.category.other', "Other"), order: 2 };

type CopilotHarnessTargetCategory = 'copilot' | 'local' | 'claude' | 'codex' | 'cloud' | 'other';

type CopilotHarnessTargetChangedEvent = {
	mode: CopilotHarnessIntroductionMode;
	fromHarness: CopilotHarnessTargetCategory;
	toHarness: CopilotHarnessTargetCategory;
	surface: 'sidebar' | 'editor';
	chatSessionId: string | undefined;
	sessionType: string | undefined;
	harness: string | undefined;
};

type CopilotHarnessTargetChangedClassification = {
	mode: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'The effective Copilot harness introduction experiment mode when the target changed.' };
	fromHarness: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'The categorized harness selected before the change.' };
	toHarness: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'The categorized harness selected after the change.' };
	surface: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'Whether the harness picker was in the sidebar or editor.' };
	chatSessionId: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'The random identifier of the chat session represented by the picker, when available.' };
	sessionType: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'The telemetry-safe chat session type represented by the picker, when available.' };
	harness: { classification: 'SystemMetaData'; purpose: 'FeatureInsight'; comment: 'The underlying Agent Host harness represented by the picker, when applicable.' };
	owner: 'justschen';
	comment: 'Tracks explicit switches into or away from the Copilot harness for the introduction experiment.';
};

function getCopilotHarnessTargetCategory(target: AgentSessionTarget, chatSessionsService: IChatSessionsService): CopilotHarnessTargetCategory {
	const provider = chatSessionsService.getChatSessionContribution(target)?.agentHostProviderId;
	if (target === AgentSessionProviders.AgentHostCopilot || target === AgentSessionProviders.Background || provider === SessionType.CopilotCLI || provider === 'copilot') {
		return 'copilot';
	}
	if (target === AgentSessionProviders.Local) {
		return 'local';
	}
	if (target === AgentSessionProviders.AgentHostClaude || provider === 'claude') {
		return 'claude';
	}
	if (target === AgentSessionProviders.Codex || target === AgentSessionProviders.AgentHostCodex || provider === 'codex') {
		return 'codex';
	}
	if (target === AgentSessionProviders.Cloud) {
		return 'cloud';
	}
	return 'other';
}

export function createSessionTypePickerAction(
	action: IAction,
	sessionTypeItem: ISessionTypeItem,
	currentType: AgentSessionTarget,
	availability: SessionTypeAvailability,
	enabled: boolean,
	category: IActionWidgetDropdownAction['category'],
	sourceDescription: string | undefined,
	icon: ThemeIcon,
	run: () => void,
): IActionWidgetDropdownAction {
	const unavailable = availability !== SessionTypeAvailability.Available;
	const description = getSessionTypeUnavailableDescription(availability) ?? sourceDescription;
	const hoverDescription = getSessionTypeUnavailableHover(availability) ?? sessionTypeItem.hoverDescription;
	const ariaDescription = description ? stripIcons(renderAsPlaintext(description)).trim() : undefined;
	const ariaHoverDescription = hoverDescription ? renderAsPlaintext(hoverDescription) : undefined;
	return {
		...action,
		id: sessionTypeItem.commandId,
		label: sessionTypeItem.label,
		checked: availability !== SessionTypeAvailability.DisabledByPolicy && currentType === sessionTypeItem.type,
		icon,
		enabled: unavailable ? false : enabled,
		category,
		description,
		ariaDescription: ariaDescription && ariaHoverDescription
			? localize('chat.sessionTarget.ariaDescription', "{0}. {1}", ariaDescription, ariaHoverDescription)
			: ariaDescription ?? ariaHoverDescription,
		tooltip: '',
		hover: { content: hoverDescription },
		run: async () => {
			if (!unavailable && enabled) {
				run();
			}
		},
	};
}

/**
 * Returns picker availability using the signed-out Agent Host setting for every chat surface.
 */
export function getConfiguredSessionTypePickerAvailability(
	type: AgentSessionTarget,
	configurationService: IConfigurationService,
	chatSessionsService: IChatSessionsService,
	chatEntitlementService: IChatEntitlementService,
	languageModelsService: ILanguageModelsService,
	agentSdkSetupService: IAgentSdkSetupService,
	codexAccountService: ICodexAccountService,
	managedSettingsService: IManagedSettingsService,
): SessionTypeAvailability {
	if (type === AgentSessionProviders.Local && requiresCopilotAgentHost(managedSettingsService, configurationService)) {
		return SessionTypeAvailability.DisabledByPolicy;
	}
	const allowSignedOutWhenUsable = configurationService.getValue<boolean>(AgentHostAllowSignedOutWhenUsableSettingId) === true;
	const hasAgentSdkSetup = hasAgentSdkSetupForSessionType(agentSdkSetupService.setups, type);
	const canInitializeWithoutGitHub = type === AgentSessionProviders.AgentHostCodex && canInitializeCodexWithoutGitHub(codexAccountService.account);
	return getSessionTypePickerAvailability(
		type,
		getSessionTypeAvailability(chatSessionsService, chatEntitlementService, languageModelsService, type, allowSignedOutWhenUsable),
		allowSignedOutWhenUsable,
		canInitializeSessionTypeOnSelection(chatEntitlementService.entitlement, allowSignedOutWhenUsable, hasAgentSdkSetup, canInitializeWithoutGitHub),
	);
}

/**
 * Action view item for selecting a session target in the chat interface.
 * This picker allows switching between different chat session types for new/empty sessions.
 */
export class SessionTypePickerActionItem extends ChatInputPickerActionViewItem {
	private _sessionTypeItems: ISessionTypeItem[] = [];
	protected readonly _isSessionsWindow: boolean;

	constructor(
		action: MenuItemAction,
		protected readonly chatSessionPosition: 'sidebar' | 'editor',
		protected readonly delegate: ISessionTypePickerDelegate,
		pickerOptions: IChatInputPickerOptions,
		private readonly inputUri: URI,
		@IActionWidgetService actionWidgetService: IActionWidgetService,
		@IKeybindingService protected readonly keybindingService: IKeybindingService,
		@IContextKeyService contextKeyService: IContextKeyService,
		@IChatSessionsService protected readonly chatSessionsService: IChatSessionsService,
		@ICommandService protected readonly commandService: ICommandService,
		@IOpenerService protected readonly openerService: IOpenerService,
		@ITelemetryService protected readonly telemetryService: ITelemetryService,
		@IChatEntitlementService protected readonly chatEntitlementService: IChatEntitlementService,
		@ILanguageModelsService protected readonly languageModelsService: ILanguageModelsService,
		@IConfigurationService protected readonly configurationService: IConfigurationService,
		@IStorageService protected readonly storageService: IStorageService,
		@IWorkspaceContextService private readonly workspaceContextService: IWorkspaceContextService,
		@IAgentHostEnablementService private readonly agentHostEnablementService: IAgentHostEnablementService,
		@IAgentSdkSetupService protected readonly agentSdkSetupService: IAgentSdkSetupService,
		@ICodexAccountService protected readonly codexAccountService: ICodexAccountService,
		@IChatHarnessSwitchFeedbackSurveyService private readonly harnessSwitchFeedbackSurveyService: IChatHarnessSwitchFeedbackSurveyService,
		@IManagedSettingsService private readonly managedSettingsService: IManagedSettingsService,
	) {

		const actionProvider: IActionWidgetDropdownActionProvider = {
			getActions: () => {
				const currentType = this._getSelectedSessionType() ?? this._getDefaultSessionType();

				const actions: IActionWidgetDropdownAction[] = [...this._getAdditionalActions().map(a => ({ ...action, ...a }))];
				for (const sessionTypeItem of this._sessionTypeItems) {
					const availability = getConfiguredSessionTypePickerAvailability(
						sessionTypeItem.type,
						this.configurationService,
						this.chatSessionsService,
						this.chatEntitlementService,
						this.languageModelsService,
						this.agentSdkSetupService,
						this.codexAccountService,
						this.managedSettingsService,
					);
					actions.push(createSessionTypePickerAction(
						action,
						sessionTypeItem,
						currentType,
						availability,
						this._isSessionTypeEnabled(sessionTypeItem.type),
						this._getSessionCategory(sessionTypeItem),
						this._getSessionDescription(sessionTypeItem),
						this._getSessionIcon(sessionTypeItem),
						() => {
							if (sessionTypeItem.type !== AgentSessionProviders.Local || !requiresCopilotAgentHost(this.managedSettingsService, this.configurationService)) {
								this._run(sessionTypeItem);
							}
						},
					));
				}

				return actions;
			}
		};

		const actionBarActionProvider: IActionProvider = {
			getActions: () => {
				return [this._getLearnMore()];
			}
		};

		const sessionTargetPickerOptions: Omit<IActionWidgetDropdownOptions, 'label' | 'labelRenderer'> = {
			actionProvider,
			actionBarActionProvider,
			showItemKeybindings: true,
			reporter: { id: 'ChatSessionTypePicker', name: `ChatSessionTypePicker`, includeOptions: true },
		};

		super(action, sessionTargetPickerOptions, pickerOptions, actionWidgetService, keybindingService, contextKeyService, telemetryService);

		this._isSessionsWindow = IsSessionsWindowContext.getValue(contextKeyService) === true;

		if (this.delegate.onDidChangeActiveSessionProvider) {
			this._register(this.delegate.onDidChangeActiveSessionProvider(() => {
				if (this.element) {
					this.renderLabel(this.element);
				}
			}));
		}

		this._register(this.chatSessionsService.onDidChangeAvailability(() => {
			this._updateAgentSessionItems();
			if (this.element) {
				this.renderLabel(this.element);
			}
		}));

		this._register(this.configurationService.onDidChangeConfiguration(e => {
			if (e.affectsConfiguration(ChatConfiguration.EditorPreferCopilotHarness) ||
				e.affectsConfiguration(ChatConfiguration.DefaultToCopilotHarness) ||
				e.affectsConfiguration(ChatConfiguration.TemporaryDefaultToLocalHarness) ||
				e.affectsConfiguration(ChatConfiguration.EditorLocalAgentEnabled)) {
				this._updateAgentSessionItems();
				if (this.element) {
					this.renderLabel(this.element);
				}
			}
		}));

		// The managed sandbox floor is delivered by managed settings, not configuration, so it needs
		// its own subscription to keep the visible harness list in sync.
		this._register(autorun(reader => {
			this.agentHostEnablementService.managedSandboxEnforced.read(reader);
			this._updateAgentSessionItems();
			if (this.element) {
				this.renderLabel(this.element);
			}
		}));

		this._register(this.workspaceContextService.onDidChangeWorkspaceFolders(() => this._updateAgentSessionItems()));
		this._register(this.managedSettingsService.onDidChangeManagedSettings(() => {
			this._updateAgentSessionItems();
			if (this.element) {
				this.renderLabel(this.element);
			}
		}));

		this._updateAgentSessionItems();
	}

	protected _run(sessionTypeItem: ISessionTypeItem): void {
		const previousTarget = this._getSelectedSessionType() ?? this._getDefaultSessionType();
		this._reportCopilotHarnessTargetChanged(sessionTypeItem.type);
		this._promptForCopilotToLocalSwitch(previousTarget, sessionTypeItem.type);

		if (!this._isSessionsWindow) {
			recordUserSelectedSessionType(this.storageService, this.configurationService, this.chatSessionsService, this.workspaceContextService.getWorkspace(), sessionTypeItem.type, this.agentHostEnablementService.enabled.get());
		}

		if (this.delegate.setActiveSessionProvider) {
			// Use provided setter (for welcome view)
			this.delegate.setActiveSessionProvider(sessionTypeItem.type);
		} else {
			// Execute command to create new session
			this.commandService.executeCommand(sessionTypeItem.commandId, this.chatSessionPosition);
		}
		if (this.element) {
			this.renderLabel(this.element);
		}
	}

	protected _reportCopilotHarnessTargetChanged(target: AgentSessionTarget): void {
		const previousTarget = this._getSelectedSessionType() ?? this._getDefaultSessionType();
		const fromHarness = getCopilotHarnessTargetCategory(previousTarget, this.chatSessionsService);
		const toHarness = getCopilotHarnessTargetCategory(target, this.chatSessionsService);
		if (previousTarget !== target && (fromHarness === 'copilot' || toHarness === 'copilot')) {
			const sessionResource = this.delegate.getSessionResource?.();
			const session = sessionResource ? getChatSessionTelemetryContext(sessionResource) : { chatSessionId: undefined, sessionType: undefined, harness: undefined };
			const mode = getCopilotHarnessIntroductionMode(this.configurationService);
			this.telemetryService.publicLog2<CopilotHarnessTargetChangedEvent, CopilotHarnessTargetChangedClassification>('copilotHarnessTargetChanged', {
				mode,
				fromHarness,
				toHarness,
				surface: this.chatSessionPosition,
				...session,
			});
		}
	}

	protected _promptForCopilotToLocalSwitch(previousTarget: AgentSessionTarget, target: AgentSessionTarget): void {
		if (previousTarget === target
			|| getCopilotHarnessTargetCategory(previousTarget, this.chatSessionsService) !== 'copilot'
			|| getCopilotHarnessTargetCategory(target, this.chatSessionsService) !== 'local') {
			return;
		}

		const sessionResource = this.delegate.getSessionResource?.();
		const session = sessionResource ? getChatSessionTelemetryContext(sessionResource) : { chatSessionId: undefined, sessionType: undefined, harness: undefined };
		this.harnessSwitchFeedbackSurveyService.prompt(this.inputUri, {
			mode: getCopilotHarnessIntroductionMode(this.configurationService),
			surface: this.chatSessionPosition,
			...session,
		});
	}

	protected _getSelectedSessionType(): AgentSessionTarget | undefined {
		return this.delegate.getActiveSessionProvider();
	}

	protected _getAdditionalActions(): IActionWidgetDropdownAction[] {
		return [];
	}

	protected _getLearnMore(): IAction {
		const learnMoreUrl = 'https://aka.ms/vscode-concept-harnesses';
		return {
			id: 'workbench.action.chat.agentOverview.learnMore',
			label: localize('chat.learnMoreAgentTypes', "Learn about harnesses..."),
			tooltip: learnMoreUrl,
			class: undefined,
			enabled: true,
			run: async () => {
				await this.openerService.open(URI.parse(learnMoreUrl));
			}
		};
	}

	private _updateAgentSessionItems(): void {
		const localSessionItem: ISessionTypeItem = {
			type: AgentSessionProviders.Local,
			label: getAgentSessionProviderName(AgentSessionProviders.Local),
			hoverDescription: getAgentSessionProviderDescription(AgentSessionProviders.Local),
			commandId: `workbench.action.chat.openNewChatSessionInPlace.${AgentSessionProviders.Local}`,
		};

		const allAgentSessionItems: ISessionTypeItem[] = [localSessionItem];

		const contributions = this.chatSessionsService.getAllChatSessionContributions();
		for (const contribution of contributions) {
			if (contribution.hideFromSessionTypePicker) {
				continue;
			}
			// TODO: Remove hardcoded providers from core
			const agentSessionType = getAgentSessionProvider(contribution.type);
			if (agentSessionType) {
				// Well-known session type — use hardcoded metadata
				allAgentSessionItems.push({
					type: agentSessionType,
					label: getAgentSessionProviderName(agentSessionType),
					hoverDescription: getAgentSessionProviderDescription(agentSessionType),
					commandId: contribution.canDelegate ?
						`workbench.action.chat.openNewChatSessionInPlace.${contribution.type}` :
						`workbench.action.chat.openNewChatSessionExternal.${contribution.type}`,
				});
			} else {
				// Extension-contributed session type — always use in-place
				// (openNewChatSessionExternal requires a menu action registered
				// by _registerMenuItems, which may not exist for extensions)
				allAgentSessionItems.push({
					type: contribution.type,
					label: contribution.displayName ?? contribution.name ?? contribution.type,
					hoverDescription: contribution.description ?? '',
					commandId: `workbench.action.chat.openNewChatSessionInPlace.${contribution.type}`,
				});
			}
		}

		// Filter out hidden items based on settings
		const agentSessionItems = allAgentSessionItems.filter(item => this._isVisible(item.type));

		// When the experimental "local agent host as default" setting is
		// enabled, hoist the agent-host item to the front of the picker so it
		// is the default selection.
		const defaultType = this._getDefaultSessionType();
		if (defaultType !== AgentSessionProviders.Local) {
			const index = agentSessionItems.findIndex(item => item.type === defaultType);
			if (index > 0) {
				const [defaultItem] = agentSessionItems.splice(index, 1);
				agentSessionItems.unshift(defaultItem);
			}
		}

		this._sessionTypeItems = agentSessionItems;
	}

	/**
	 * The default session type for the picker when no session is yet active.
	 * Defaults to Agent Host Copilot when the agent host is enabled, otherwise
	 * {@link AgentSessionProviders.Local}.
	 */
	protected _getDefaultSessionType(): AgentSessionTarget {
		return getDefaultNewChatSessionType(this.configurationService, this.chatSessionsService, this.storageService, this.workspaceContextService.getWorkspace(), this.agentHostEnablementService.enabled.get(), undefined, this.agentHostEnablementService.managedSandboxEnforced.get(), requiresCopilotAgentHost(this.managedSettingsService, this.configurationService)) as AgentSessionTarget;
	}

	protected _isVisible(type: AgentSessionTarget): boolean {
		return isVisibleEditorChatSessionType(type, this.configurationService, this.chatSessionsService, this.workspaceContextService.getWorkspace(), this.agentHostEnablementService.managedSandboxEnforced.get(), this.agentHostEnablementService.enabled.get(), requiresCopilotAgentHost(this.managedSettingsService, this.configurationService));
	}

	protected _isSessionTypeEnabled(type: AgentSessionTarget): boolean {
		if (type === AgentSessionProviders.Local) {
			return !requiresCopilotAgentHost(this.managedSettingsService, this.configurationService);
		}
		// Disable non-local session types when their provider is not registered yet
		return !!this.chatSessionsService.getChatSessionContribution(type);
	}

	protected _getSessionCategory(sessionTypeItem: ISessionTypeItem) {
		// TODO: Remove hardcoded providers from core
		const knownType = getAgentSessionProvider(sessionTypeItem.type);
		return knownType && isFirstPartyAgentSessionProvider(knownType) ? firstPartyCategory : otherCategory;
	}

	protected _getSessionDescription(_sessionTypeItem: ISessionTypeItem): string | undefined {
		return undefined;
	}

	protected _getSessionLabel(type: AgentSessionTarget): string {
		const knownType = getAgentSessionProvider(type);
		return knownType
			? getAgentSessionProviderName(knownType)
			: (this.chatSessionsService.getChatSessionContribution(type)?.displayName ?? type);
	}

	private _getSessionIcon(sessionTypeItem: ISessionTypeItem): ThemeIcon {
		// TODO: Remove hardcoded providers from core
		const knownType = getAgentSessionProvider(sessionTypeItem.type);
		if (knownType) {
			return getAgentSessionProviderIcon(knownType);
		}
		// Extension-contributed: look up icon from the contribution
		const contribution = this.chatSessionsService.getChatSessionContribution(sessionTypeItem.type);
		if (contribution && ThemeIcon.isThemeIcon(contribution.icon)) {
			return contribution.icon;
		}
		return Codicon.extensions;
	}

	override render(container: HTMLElement): void {
		super.render(container);
		container.classList.add('chat-session-target-picker-item');
	}

	protected override updateEnabled(): void {
		super.updateEnabled();
		this.element?.setAttribute('aria-disabled', String(!this.isEnabled()));
	}

	protected override renderLabel(element: HTMLElement): IDisposable | null {
		const currentType = this._getSelectedSessionType() ?? this._getDefaultSessionType();
		const label = this._getSessionLabel(currentType);
		const icon = this._getSessionIcon({ type: currentType, label, hoverDescription: '', commandId: '' });

		const labelElements = [];
		labelElements.push(...renderLabelWithIcons(`$(${getCompactCodicon(icon).id})`));
		const compact = this.pickerOptions.compact.get();
		element.classList.toggle('icon-only', compact);
		if (!compact) {
			labelElements.push(dom.$('span.chat-input-picker-label', undefined, label));
		}

		dom.reset(element, ...labelElements);
		this.updateTooltip();
		element.ariaLabel = label;

		return null;
	}
}
