export const enum MarketplaceType {
	Copilot = 'copilot',
	Claude = 'claude',
	OpenPlugin = 'openPlugin',
}

export const enum PluginSourceKind {
	RelativePath = 'relativePath',
	GitHub = 'github',
	GitUrl = 'url',
	Npm = 'npm',
	Pip = 'pip',
}

export interface IRelativePathPluginSource {
	readonly kind: PluginSourceKind.RelativePath;
	/** Resolved relative path within the marketplace repository. */
	readonly path: string;
}

export interface IGitHubPluginSource {
	readonly kind: PluginSourceKind.GitHub;
	readonly repo: string;
	readonly ref?: string;
	readonly sha?: string;
	readonly path?: string;
}

export interface IGitUrlPluginSource {
	readonly kind: PluginSourceKind.GitUrl;
	/** Full git repository URL (must end with .git). */
	readonly url: string;
	readonly ref?: string;
	readonly sha?: string;
	/** Subdirectory within the repository where the plugin lives (for `git-subdir` sources). */
	readonly path?: string;
}

export interface INpmPluginSource {
	readonly kind: PluginSourceKind.Npm;
	readonly package: string;
	readonly version?: string;
	readonly registry?: string;
}

export interface IPipPluginSource {
	readonly kind: PluginSourceKind.Pip;
	readonly package: string;
	readonly version?: string;
	readonly registry?: string;
}

export type IPluginSourceDescriptor =
	| IRelativePathPluginSource
	| IGitHubPluginSource
	| IGitUrlPluginSource
	| INpmPluginSource
	| IPipPluginSource;

export interface IMarketplacePlugin {
	readonly name: string;
	readonly description: string;
	readonly version: string;
	/** Subdirectory within the repository where the plugin lives (for relative-path sources). */
	readonly source: string;
	/** Structured source descriptor indicating how the plugin should be fetched/installed. */
	readonly sourceDescriptor: IPluginSourceDescriptor;
	/** Marketplace label shown in UI and plugin provenance. */
	readonly marketplace: string;
	/** Marketplace manifest name used by the SDK's `plugin@marketplace` identity. */
	readonly marketplaceName?: string;
	/** Canonical reference for clone/update/install location resolution. */
	readonly marketplaceReference: IMarketplaceReference;
	/** The type of marketplace this plugin comes from. */
	readonly marketplaceType: MarketplaceType;
	readonly readmeUri?: URI;
}

/** Raw JSON shape of a remote plugin source object in marketplace.json. */
interface IJsonPluginSource {
	readonly source: string;
	readonly repo?: string;
	readonly url?: string;
	readonly package?: string;
	readonly ref?: string;
	readonly sha?: string;
	readonly path?: string;
	readonly version?: string;
	readonly registry?: string;
}

interface IMarketplaceJson {
	readonly name?: string;
	readonly metadata?: {
		readonly pluginRoot?: string;
	};
	readonly plugins?: readonly {
		readonly name?: string;
		readonly description?: string;
		readonly version?: string;
		readonly source?: string | IJsonPluginSource;
	}[];
}

export interface IMarketplaceInstalledPlugin {
	readonly pluginUri: URI;
	readonly plugin: IMarketplacePlugin;
}

/**
 * Options for fetching marketplace plugins.
 */
export interface IFetchMarketplacePluginsOptions {
	/** Bypass the marketplace caches (HTTP TTL cache and cloned-repository TTL) and re-read from the remote. */
	readonly refresh?: boolean;
	/**
	 * Called for each marketplace that could not be read. Individual failures
	 * are otherwise swallowed so that one bad marketplace cannot fail the
	 * whole fetch, which leaves callers unable to tell a partial result from
	 * a complete one.
	 */
	readonly onMarketplaceError?: (reference: IMarketplaceReference, error: unknown) => void;
}

export interface IPluginMarketplaceQuery {
	readonly text?: string;
	readonly pageSize: number;
	readonly cursor?: string;
	readonly marketplaceIds: ReadonlySet<string>;
	readonly marketplaceTypes: ReadonlySet<MarketplaceType>;
}

export interface IPluginMarketplacePage {
	readonly items: readonly IMarketplacePlugin[];
	readonly total?: number;
	readonly nextCursor?: string;
	readonly errors: readonly { readonly marketplace: string; readonly message: string }[];
}

export const IPluginMarketplaceService = createDecorator<IPluginMarketplaceService>('pluginMarketplaceService');

export interface IPluginMarketplaceService {
	readonly _serviceBrand: undefined;
	readonly onDidChangeMarketplaces: Event<void>;
	/** Installed marketplace plugins, backed by storage. */
	readonly installedPlugins: IObservable<readonly IMarketplaceInstalledPlugin[]>;
	/** Canonical IDs of marketplaces with updates detected by the periodic check. */
	readonly marketplacesWithUpdates: IObservable<ReadonlySet<string>>;
	/**
	 * Observable snapshot of the last {@link fetchMarketplacePlugins} result.
	 * Empty until the first fetch completes. Views should use this for
	 * synchronous outdated-detection instead of calling fetchMarketplacePlugins.
	 */
	readonly lastFetchedPlugins: IObservable<readonly IMarketplacePlugin[]>;
	/**
	 * Set of recommended plugin keys (`"pluginName@marketplaceName"`) aggregated
	 * from workspace-defined settings (e.g. `.claude/settings.json`). Providers
	 * may be added over time; consumers should not assume a specific source.
	 */
	readonly recommendedPlugins: IObservable<ReadonlySet<string>>;
	/** Clears all reported marketplaces, or only the provided canonical IDs. */
	clearUpdatesAvailable(marketplaceIds?: ReadonlySet<string>): void;
	/** Returns the effective, policy-filtered marketplace references in query order. */
	getMarketplaceReferences(): readonly IMarketplaceReference[];
	/** Queries a stable, opaque page over selected existing Plugin marketplaces. */
	queryMarketplacePlugins(options: IPluginMarketplaceQuery, token: CancellationToken): Promise<IPluginMarketplacePage>;
	fetchMarketplacePlugins(token: CancellationToken, marketplaceIds?: ReadonlySet<string>, options?: IFetchMarketplacePluginsOptions): Promise<IMarketplacePlugin[]>;
	getMarketplacePluginMetadata(pluginUri: URI): IMarketplacePlugin | undefined;
	/** Records an installation, retaining its enablement identity when moving from a previous URI. */
	addInstalledPlugin(pluginUri: URI, plugin: IMarketplacePlugin, previousPluginUri?: URI): void;
	/** Removes the exact durable installed entry, including when its metadata is not hydrated. */
	removeInstalledPlugin(pluginUri: URI): boolean;
	/** Returns whether the given marketplace is trusted — either explicitly trusted by the user, or allowed by the enterprise allowlist when strict mode is active. */
	isMarketplaceTrusted(ref: IMarketplaceReference): boolean;
	/**
	 * Returns whether the strict-marketplace enterprise policy
	 * (`strictKnownMarketplaces`) is active — i.e. an allowlist is
	 * configured. When active, blocked marketplaces cannot be trusted by the user.
	 */
	isStrictMarketplacePolicyActive(): boolean;
	/** Returns the effective automatic-update policy for a marketplace. */
	isMarketplaceAutoUpdateEnabled(ref: IMarketplaceReference): boolean;
	/** Records that the user trusts the given marketplace, persisted permanently. */
	trustMarketplace(ref: IMarketplaceReference): void;
	/**
	 * Reads marketplace definition files from an already-cloned repository
	 * directory and returns the declared plugins. Used by direct-install flows
	 * that clone a repo first, then need to discover its plugins.
	 */
	readPluginsFromDirectory(repoDir: URI, reference: IMarketplaceReference): Promise<IMarketplacePlugin[]>;
	/**
	 * Reads a single-plugin manifest (e.g. `.claude-plugin/plugin.json`) at the
	 * root of an already-cloned repository directory and returns a synthesised
	 * {@link IMarketplacePlugin} describing the repository as a single plugin.
	 * Used by direct-install flows when {@link readPluginsFromDirectory} finds
	 * no marketplace index.
	 *
	 * Returns `undefined` when no recognised manifest is present at the repo
	 * root.
	 */
	readSinglePluginManifest(repoDir: URI, reference: IMarketplaceReference): Promise<IMarketplacePlugin | undefined>;
	/**
	 * Returns whether the given directory is a standalone plugin — i.e. it
	 * contains a single-plugin manifest (e.g. `.plugin/plugin.json`,
	 * `.claude-plugin/plugin.json`, or `plugin.json`) at its root but is not a
	 * marketplace. Used by direct-install flows to route a local folder to the
	 * appropriate configuration.
	 */
	isPluginDirectory(repoDir: URI): Promise<boolean>;
}

/**
 * Marketplace definition files by type, checked in order per repository.
 * The first match determines the marketplace type.
 */
const MARKETPLACE_DEFINITIONS: { type: MarketplaceType; path: string }[] = [
	{ type: MarketplaceType.OpenPlugin, path: 'marketplace.json' },
	{ type: MarketplaceType.OpenPlugin, path: '.plugin/marketplace.json' },
	{ type: MarketplaceType.Copilot, path: '.github/plugin/marketplace.json' },
	{ type: MarketplaceType.Claude, path: '.claude-plugin/marketplace.json' },
];

/**
 * Single-plugin manifest files by type, checked in order. Used when a cloned
 * source repository has no marketplace index — the repository itself is the
 * plugin. Order matches {@link detectPluginFormat} so that runtime format
 * detection later agrees with the marketplace type chosen here.
 */
const SINGLE_PLUGIN_MANIFEST_DEFINITIONS: { type: MarketplaceType; path: string }[] = [
	{ type: MarketplaceType.OpenPlugin, path: '.plugin/plugin.json' },
	{ type: MarketplaceType.Claude, path: '.claude-plugin/plugin.json' },
	{ type: MarketplaceType.Copilot, path: 'plugin.json' },
];

const GITHUB_MARKETPLACE_CACHE_TTL_MS = 8 * 60 * 60 * 1000;
// Ignore catalogs persisted before Git source path validation.
const GITHUB_MARKETPLACE_CACHE_STORAGE_KEY = 'chat.plugins.marketplaces.githubCache.v2';

/** Interval between periodic plugin update checks (24 hours). */
const PLUGIN_UPDATE_CHECK_INTERVAL_MS = 24 * 60 * 60 * 1000;

const PLUGIN_UPDATE_LAST_CHECK_STORAGE_KEY = 'chat.plugins.lastUpdateCheck.v1';

interface IGitHubMarketplaceCacheEntry {
	readonly plugins: readonly IMarketplacePlugin[];
	readonly expiresAt: number;
	readonly referenceRawValue: string;
}

type IStoredGitHubMarketplaceCache = Dto<Record<string, IGitHubMarketplaceCacheEntry>>;

/**
 * Ensures that an {@link IMarketplacePlugin} loaded from storage has a
 * {@link IMarketplacePlugin.sourceDescriptor sourceDescriptor}. Plugins
 * persisted before the sourceDescriptor field was introduced will only
 * have the legacy `source` string — this function synthesises a
 * {@link PluginSourceKind.RelativePath} descriptor from it.
 */
function ensureSourceDescriptor(plugin: IMarketplacePlugin): IMarketplacePlugin {
	if (plugin.sourceDescriptor) {
		return plugin;
	}
	return {
		...plugin,
		sourceDescriptor: { kind: PluginSourceKind.RelativePath, path: plugin.source },
	};
}

const trustedMarketplacesMemento = observableMemento<readonly string[]>({
	defaultValue: [],
	key: 'chat.plugins.trustedMarketplaces.v1',
	toStorage: value => JSON.stringify(value),
	fromStorage: value => {
		const parsed = JSON.parse(value);
		return Array.isArray(parsed) ? parsed : [];
	},
});

interface IStoredLastFetchedPlugins {
	readonly plugins: readonly IMarketplacePlugin[];
	readonly fetchedAt: number;
}

const lastFetchedPluginsMemento = observableMemento<IStoredLastFetchedPlugins>({
	defaultValue: { plugins: [], fetchedAt: 0 },
	key: 'chat.plugins.lastFetchedPlugins.v2',
	toStorage: value => JSON.stringify(value),
	fromStorage: value => {
		const parsed = JSON.parse(value);
		if (parsed && Array.isArray(parsed.plugins)) {
			return parsed;
		}
		return { plugins: [], fetchedAt: 0 };
	},
});

const maxPluginMarketplaceContinuations = 32;
const maxPluginMarketplacePageSize = 100;
const pluginMarketplaceContinuationLifetimeMs = 30 * 60_000;

interface IPluginMarketplaceContinuation {
	readonly text: string;
	readonly pageSize: number;
	readonly marketplaceIds: readonly string[];
	readonly marketplaceTypes: readonly MarketplaceType[];
	readonly items: readonly IMarketplacePlugin[];
	readonly errors: readonly { readonly marketplace: string; readonly message: string }[];
	readonly offset: number;
	readonly expiresAt: number;
}

export class PluginMarketplaceService extends Disposable implements IPluginMarketplaceService {
	declare readonly _serviceBrand: undefined;
	private readonly _gitHubMarketplaceCache = new Lazy<Map<string, IGitHubMarketplaceCacheEntry>>(() => this._loadPersistedGitHubMarketplaceCache());
	private readonly _installedPluginsStore: FileBackedInstalledPluginsStore;
	private readonly _pluginMetadata = new Map<string, IMarketplacePlugin>();
	private readonly _trustedMarketplacesStore: ObservableMemento<readonly string[]>;
	private readonly _lastFetchedPluginsStore: ObservableMemento<IStoredLastFetchedPlugins>;
	private readonly _marketplacesWithUpdates = observableValue<ReadonlySet<string>>('marketplacesWithUpdates', new Set());
	private readonly _updateCheckDelayer = this._register(new ThrottledDelayer<void>(PLUGIN_UPDATE_CHECK_INTERVAL_MS));
	private readonly _queryContinuations = new LRUCache<string, IPluginMarketplaceContinuation>(maxPluginMarketplaceContinuations);
	private _updateChecksInitialized = false;
	private _updateCheckRunning = false;
	private _queryGeneration = 0;

	readonly onDidChangeMarketplaces: Event<void>;

	readonly installedPlugins: IObservable<readonly IMarketplaceInstalledPlugin[]>;
	readonly marketplacesWithUpdates: IObservable<ReadonlySet<string>> = this._marketplacesWithUpdates;
	readonly lastFetchedPlugins: IObservable<readonly IMarketplacePlugin[]>;
	readonly recommendedPlugins: IObservable<ReadonlySet<string>>;

	constructor(
		@IConfigurationService private readonly _configurationService: IConfigurationService,
		@IRequestService private readonly _requestService: IRequestService,
		@IEnvironmentService environmentService: IEnvironmentService,
		@IFileService private readonly _fileService: IFileService,
		@IAgentPluginRepositoryService private readonly _pluginRepositoryService: IAgentPluginRepositoryService,
		@ILogService private readonly _logService: ILogService,
		@IStorageService private readonly _storageService: IStorageService,
		@IWorkspacePluginSettingsService private readonly _workspacePluginSettingsService: IWorkspacePluginSettingsService,
		@IWorkspaceTrustManagementService private readonly _workspaceTrustService: IWorkspaceTrustManagementService,
		@IExtensionsWorkbenchService private readonly _extensionsWorkbenchService: IExtensionsWorkbenchService,
		@IMeteredConnectionService private readonly _meteredConnectionService: IMeteredConnectionService,
		@IAgentPluginEnablementService pluginEnablementService: IAgentPluginEnablementService,
		@IManagedSettingsService private readonly _managedSettingsService: IManagedSettingsService,
	) {
		super();

		// File-backed store for installed plugins. The old cache location
		// is passed so the store can rebase URIs during migration.
		const oldCacheRoot = joinPath(environmentService.cacheHome, 'agentPlugins');
		this._installedPluginsStore = this._register(
			new FileBackedInstalledPluginsStore(
				_pluginRepositoryService.agentPluginsHome,
				oldCacheRoot,
				_fileService,
				_logService,
				_storageService,
				pluginEnablementService,
			)
		);

		this._trustedMarketplacesStore = this._register(
			trustedMarketplacesMemento(StorageScope.APPLICATION, StorageTarget.MACHINE, _storageService)
		);

		this._lastFetchedPluginsStore = this._register(
			lastFetchedPluginsMemento(StorageScope.APPLICATION, StorageTarget.MACHINE, _storageService)
		);

		this.lastFetchedPlugins = this._lastFetchedPluginsStore.map(s => {
			const revived = revive(s) as IStoredLastFetchedPlugins;
			return revived.plugins.map(ensureSourceDescriptor);
		});

		this.installedPlugins = this._installedPluginsStore.value.map(entries => {
			const result: IMarketplaceInstalledPlugin[] = [];
			for (const e of entries) {
				const plugin = this._pluginMetadata.get(e.pluginUri.toString());
				if (plugin) {
					result.push({ pluginUri: e.pluginUri, plugin });
				}
			}
			return result;
		});

		// Aggregate recommended plugin keys from all providers.
		// Currently sourced from Claude workspace settings; more providers can be
		// added here via additional observables in the derived computation.
		// Only expose recommendations when the workspace is trusted.
		const workspaceTrusted = observableFromEvent(this, this._workspaceTrustService.onDidChangeTrust, () => this._workspaceTrustService.isWorkspaceTrusted());
		this.recommendedPlugins = derived(reader => {
			if (!workspaceTrusted.read(reader)) {
				return new Set<string>();
			}
			const enabledMap = this._workspacePluginSettingsService.enabledPlugins.read(reader);
			const keys = new Set<string>();
			for (const [key, value] of enabledMap) {
				if (value) {
					keys.add(key);
				}
			}
			return keys;
		});

		const strictMarketplaces = observableFromEvent(this, this._managedSettingsService.onDidChangeManagedSettings,
			() => this._managedSettingsService.getManagedSettingValue(COPILOT_STRICT_MARKETPLACES_KEY));
		this.onDidChangeMarketplaces = Event.any(
			Event.filter(
				_configurationService.onDidChangeConfiguration,
				e => e.affectsConfiguration(ChatConfiguration.PluginsEnabled) ||
					e.affectsConfiguration(ChatConfiguration.PluginMarketplaces) ||
					e.affectsConfiguration(ChatConfiguration.ExtraMarketplaces),
			) as Event<unknown> as Event<void>,
			Event.fromObservableLight(this._workspacePluginSettingsService.extraMarketplaces),
			Event.map(this._workspaceTrustService.onDidChangeTrust, () => { }),
			Event.fromObservableLight(strictMarketplaces),
		);
		this._register(this.onDidChangeMarketplaces(() => this._invalidateQueries()));

		this._register(runWhenGlobalIdle(() => {
			this._updateChecksInitialized = true;
			this._scheduleUpdateCheck();
			this._register(Event.any(
				Event.filter(
					_configurationService.onDidChangeConfiguration,
					e => e.affectsConfiguration(AutoUpdateConfigurationKey)
						|| e.affectsConfiguration(ChatConfiguration.ExtraMarketplaces),
				),
				Event.fromObservableLight(strictMarketplaces),
			)(() => {
				this._marketplacesWithUpdates.set(new Set(), undefined);
				this._scheduleUpdateCheck(0);
			}));
			this._register(this._meteredConnectionService.onDidChangeIsConnectionMetered(isMetered => {
				if (isMetered) {
					this._updateCheckDelayer.cancel();
				} else if (!this._updateCheckRunning && !this._updateCheckDelayer.isTriggered()) {
					this._scheduleUpdateCheck();
				}
			}));
		}));

		// Hydrate plugin metadata for installed entries that are not yet in
		// the in-memory cache (e.g. after restart when installed.json is read
		// but the metadata map is empty). Modern entries match by plugin name;
		// older entries without names fall back to matching by install URI.
		this._register(autorun(reader => {
			const entries = this._installedPluginsStore.value.read(reader);
			const unhydrated = entries.filter(e => !this._pluginMetadata.has(e.pluginUri.toString()));
			if (unhydrated.length > 0) {
				this._hydratePluginMetadata(unhydrated);
			}
		}));
	}

	clearUpdatesAvailable(marketplaceIds?: ReadonlySet<string>): void {
		const remaining = marketplaceIds
			? new Set([...this._marketplacesWithUpdates.get()].filter(id => !marketplaceIds.has(id)))
			: new Set<string>();
		this._marketplacesWithUpdates.set(remaining, undefined);

		if (remaining.size === 0
			&& this._updateChecksInitialized
			&& !this._updateCheckRunning
			&& !this._updateCheckDelayer.isTriggered()) {
			this._scheduleUpdateCheck();
		}
	}

	getMarketplaceReferences(): readonly IMarketplaceReference[] {
		return this._getConfiguredMarketplaceReferences().filter(reference => this._isMarketplaceAllowedByStrictPolicy(reference));
	}

	async queryMarketplacePlugins(options: IPluginMarketplaceQuery, token: CancellationToken): Promise<IPluginMarketplacePage> {
		if (token.isCancellationRequested) {
			throw new CancellationError();
		}
		const text = options.text?.trim().toLowerCase() ?? '';
		const pageSize = Math.min(options.pageSize, maxPluginMarketplacePageSize);
		const marketplaceIds = [...options.marketplaceIds].sort();
		const marketplaceTypes = [...options.marketplaceTypes].sort();
		if (!Number.isSafeInteger(options.pageSize) || options.pageSize <= 0 || marketplaceIds.length !== options.marketplaceIds.size ||
			marketplaceTypes.length !== options.marketplaceTypes.size) {
			throw new Error(localize('pluginMarketplace.invalidPage', "The plugin marketplace page is invalid. Start a new search."));
		}
		for (const [key, value] of [...this._queryContinuations]) {
			if (value.expiresAt <= Date.now()) {
				this._queryContinuations.delete(key);
			}
		}
		const continuation = options.cursor ? this._queryContinuations.get(options.cursor) : undefined;
		if (options.cursor && (!continuation || continuation.text !== text || continuation.pageSize !== pageSize ||
			!equals(continuation.marketplaceIds, marketplaceIds) || !equals(continuation.marketplaceTypes, marketplaceTypes))) {
			throw new Error(localize('pluginMarketplace.invalidPage', "The plugin marketplace page is invalid. Start a new search."));
		}
		const generation = this._queryGeneration;
		const errors: { marketplace: string; message: string }[] = [];
		const plugins = continuation ? [] : await this.fetchMarketplacePlugins(token, new Set(marketplaceIds), {
			onMarketplaceError: (reference, error) => errors.push({ marketplace: reference.displayLabel, message: getErrorMessage(error) }),
		});
		if (token.isCancellationRequested || generation !== this._queryGeneration) {
			throw new CancellationError();
		}
		const items = continuation?.items ?? plugins.filter(plugin =>
			options.marketplaceTypes.has(plugin.marketplaceType) &&
			(!text || [plugin.name, plugin.description, plugin.marketplace].some(value => value.toLowerCase().includes(text))));
		const offset = continuation?.offset ?? 0;
		const end = Math.min(offset + pageSize, items.length);
		const nextCursor = end < items.length ? generateUuid() : undefined;
		if (nextCursor) {
			this._queryContinuations.set(nextCursor, {
				text,
				pageSize,
				marketplaceIds,
				marketplaceTypes,
				items,
				errors: continuation?.errors ?? errors,
				offset: end,
				expiresAt: Date.now() + pluginMarketplaceContinuationLifetimeMs,
			});
		}
		const pageErrors = continuation?.errors ?? errors;
		return {
			items: items.slice(offset, end),
			total: pageErrors.length ? undefined : items.length,
			nextCursor,
			errors: pageErrors,
		};
	}

	async fetchMarketplacePlugins(token: CancellationToken, marketplaceIds?: ReadonlySet<string>, options?: IFetchMarketplacePluginsOptions): Promise<IMarketplacePlugin[]> {
		if (!this._configurationService.getValue<boolean>(ChatConfiguration.PluginsEnabled)) {
			return [];
		}

		// Effective set: user-facing `chat.plugins.marketplaces` (default + user)
		// unioned with the enterprise policy-only `chat.plugins.extraMarketplaces`.
		// `parseMarketplaceReferences` dedupes by canonical id.
		const { effectiveValues } = readConfiguredMarketplaces(this._configurationService);

		for (const value of effectiveValues) {
			const parsed = typeof value === 'string'
				? parseMarketplaceReference(value)
				: (value && typeof value === 'object' ? parseMarketplaceObjectEntry(value as Parameters<typeof parseMarketplaceObjectEntry>[0]) : undefined);
			if (!parsed) {
				this._logService.debug(`[PluginMarketplaceService] Ignoring invalid marketplace entry: ${String(value)}`);
			}
		}

		const refsToFetch = this.getMarketplaceReferences().filter(ref => !marketplaceIds || marketplaceIds.has(ref.canonicalId));
		const results = await Promise.all(
			refsToFetch.map(ref => {
				if (ref.kind === MarketplaceReferenceKind.GitHubShorthand && ref.githubRepo) {
					return this._fetchFromGitHubRepo(ref, ref.githubRepo, token, options);
				}
				return this._fetchFromClonedRepo(ref, token, options);
			})
		);
		const plugins = results.flat();

		// A cancelled fetch yields empty/partial results — committing those
		// would wipe the observable list and blank out the marketplace UI.
		if (token.isCancellationRequested) {
			return plugins;
		}

		const storedPlugins = marketplaceIds
			? [...this.lastFetchedPlugins.get().filter(plugin => !marketplaceIds.has(plugin.marketplaceReference.canonicalId)), ...plugins]
			: plugins;
		this._lastFetchedPluginsStore.set({ plugins: storedPlugins, fetchedAt: Date.now() }, undefined);
		return plugins;
	}

	private _getConfiguredMarketplaceReferences(): readonly IMarketplaceReference[] {
		const { effectiveValues } = readConfiguredMarketplaces(this._configurationService);
		const configured = parseMarketplaceReferences(effectiveValues);
		if (!this._workspaceTrustService.isWorkspaceTrusted()) {
			return configured;
		}
		const workspaceEntries = this._workspacePluginSettingsService.extraMarketplaces.get();
		return deduplicateMarketplaceReferences(workspaceEntries.map(entry => entry.reference), configured);
	}

	private _invalidateQueries(): void {
		this._queryGeneration++;
		this._queryContinuations.clear();
	}

	private async _fetchFromGitHubRepo(reference: IMarketplaceReference, repo: string, token: CancellationToken, options?: IFetchMarketplacePluginsOptions): Promise<IMarketplacePlugin[]> {
		const cache = this._gitHubMarketplaceCache.value;

		const cached = options?.refresh ? undefined : this._getCachedGitHubMarketplacePlugins(cache, reference.canonicalId);
		if (cached) {
			return cached.map(c => {
				const plugin = ensureSourceDescriptor(c);
				return {
					...plugin,
					marketplace: reference.displayLabel,
					marketplaceReference: reference,
					readmeUri: getMarketplaceReadmeUri(plugin.sourceDescriptor, reference, plugin.source),
				};
			});
		}

		let repoMayBePrivate = true;
		let readError: Error | undefined;

		const plugins = await this._readPluginsFromDefinitions(reference, async (defPath) => {
			if (token.isCancellationRequested) {
				return undefined;
			}
			const ref = encodeURIComponent(reference.ref ?? 'main');
			const url = `https://raw.githubusercontent.com/${repo}/${ref}/${defPath}`;
			try {
				const context = await this._requestService.request({ type: 'GET', url, callSite: 'pluginMarketplaceService.fetchPluginList' }, token);
				const statusCode = context.res.statusCode;
				if (statusCode !== 200) {
					repoMayBePrivate &&= statusCode !== undefined && statusCode >= 400 && statusCode < 500;
					if (statusCode === undefined || statusCode >= 500 || statusCode === 429) {
						readError = new Error(localize('pluginMarketplace.httpReadFailed', "Unable to read marketplace '{0}' (HTTP {1}).", reference.displayLabel, statusCode ?? 'unknown'));
					}
					this._logService.debug(`[PluginMarketplaceService] ${url} returned status ${statusCode}, skipping`);
					return undefined;
				}
				return await asJson<IMarketplaceJson>(context) ?? undefined;
			} catch (err) {
				readError = new Error(localize('pluginMarketplace.readFailed', "Unable to read marketplace '{0}'.", reference.displayLabel));
				this._logService.debug(`[PluginMarketplaceService] Failed to fetch marketplace.json from ${url}:`, err);
				return undefined;
			}
		});

		if (plugins.length > 0) {
			cache.set(reference.canonicalId, {
				plugins,
				expiresAt: Date.now() + GITHUB_MARKETPLACE_CACHE_TTL_MS,
				referenceRawValue: reference.rawValue,
			});
			this._savePersistedGitHubMarketplaceCache(cache);
			return plugins;
		}

		if (repoMayBePrivate) {
			this._logService.debug(`[PluginMarketplaceService] ${repo} may be private, attempting clone-based marketplace discovery`);

			// Drop any raw-fetch entry cached while the repository was still
			// public, otherwise the next non-forced fetch would serve it in
			// preference to the clone until its original TTL expired.
			if (cache.delete(reference.canonicalId)) {
				this._savePersistedGitHubMarketplaceCache(cache);
			}

			let cloneFailed = false;
			const cloned = await this._fetchFromClonedRepo(reference, token, {
				...options,
				onMarketplaceError: (ref, error) => {
					cloneFailed = true;
					options?.onMarketplaceError?.(ref, error);
				},
			});
			if (!cloned.length && readError && !cloneFailed && !token.isCancellationRequested) {
				options?.onMarketplaceError?.(reference, readError);
			}
			return cloned;
		}

		if (readError && !token.isCancellationRequested) {
			options?.onMarketplaceError?.(reference, readError);
		}
		this._logService.debug(`[PluginMarketplaceService] No marketplace.json found in ${repo}`);
		return [];
	}

	private _getCachedGitHubMarketplacePlugins(cache: Map<string, IGitHubMarketplaceCacheEntry>, cacheKey: string): IMarketplacePlugin[] | undefined {
		const cached = cache.get(cacheKey);
		if (!cached) {
			return undefined;
		}

		if (cached.expiresAt <= Date.now()) {
			cache.delete(cacheKey);
			this._savePersistedGitHubMarketplaceCache(cache);
			return undefined;
		}

		return [...cached.plugins];
	}

	private _loadPersistedGitHubMarketplaceCache(): Map<string, IGitHubMarketplaceCacheEntry> {
		const cache = new Map<string, IGitHubMarketplaceCacheEntry>();
		const now = Date.now();
		const stored = this._storageService.getObject<IStoredGitHubMarketplaceCache>(GITHUB_MARKETPLACE_CACHE_STORAGE_KEY, StorageScope.APPLICATION);
		if (!stored) {
			return cache;
		}

		const revived = revive<IStoredGitHubMarketplaceCache>(stored);

		for (const [cacheKey, entry] of Object.entries(revived)) {
			if (!entry || !Array.isArray(entry.plugins) || typeof entry.expiresAt !== 'number' || entry.expiresAt <= now || typeof entry.referenceRawValue !== 'string') {
				continue;
			}

			const reference = parseMarketplaceReference(entry.referenceRawValue);
			if (!reference) {
				continue;
			}

			const plugins = entry.plugins.map(plugin => ensureSourceDescriptor({
				...plugin,
				marketplace: reference.displayLabel,
				marketplaceReference: reference,
			}));

			cache.set(cacheKey, {
				plugins,
				expiresAt: entry.expiresAt,
				referenceRawValue: entry.referenceRawValue,
			});
		}

		return cache;
	}

	private _savePersistedGitHubMarketplaceCache(cache: Map<string, IGitHubMarketplaceCacheEntry>): void {
		const serialized: IStoredGitHubMarketplaceCache = {};
		for (const [cacheKey, entry] of cache) {
			if (!entry.plugins.length || entry.expiresAt <= Date.now()) {
				continue;
			}

			serialized[cacheKey] = {
				expiresAt: entry.expiresAt,
				referenceRawValue: entry.referenceRawValue,
				plugins: entry.plugins,
			};
		}

		if (Object.keys(serialized).length === 0) {
			this._storageService.remove(GITHUB_MARKETPLACE_CACHE_STORAGE_KEY, StorageScope.APPLICATION);
			return;
		}

		this._storageService.store(
			GITHUB_MARKETPLACE_CACHE_STORAGE_KEY,
			JSON.stringify(serialized),
			StorageScope.APPLICATION,
			StorageTarget.MACHINE,
		);
	}

	getMarketplacePluginMetadata(pluginUri: URI): IMarketplacePlugin | undefined {
		return this._pluginMetadata.get(pluginUri.toString())
			?? [...this._pluginMetadata.entries()].find(([key]) => isEqualOrParent(pluginUri, URI.parse(key)))?.[1];
	}

	addInstalledPlugin(pluginUri: URI, plugin: IMarketplacePlugin, previousPluginUri?: URI): void {
		this._pluginMetadata.set(pluginUri.toString(), plugin);
		const current = this._installedPluginsStore.get();
		const existing = current.find(e => isEqual(e.pluginUri, pluginUri));
		const previous = previousPluginUri ? current.find(e => isEqual(e.pluginUri, previousPluginUri)) : undefined;
		const identitySource = previous ?? existing;
		const entry: IStoredInstalledPlugin = {
			...existing,
			...(previousPluginUri ? { enablementUri: identitySource?.enablementUri ?? identitySource?.pluginUri ?? previousPluginUri } : {}),
			pluginUri,
			marketplace: plugin.marketplaceReference.rawValue,
			name: plugin.name,
		};
		if (existing) {
			// Still update to trigger watchers to re-check, something might have happened that we want to know about
			this._installedPluginsStore.set(current.map(c => c === existing ? entry : c), undefined);
		} else {
			this._installedPluginsStore.set([...current, entry], undefined);
		}
	}

	removeInstalledPlugin(pluginUri: URI): boolean {
		this._pluginMetadata.delete(pluginUri.toString());
		const current = this._installedPluginsStore.get();
		if (!current.some(entry => isEqual(entry.pluginUri, pluginUri))) {
			return false;
		}
		this._installedPluginsStore.set(current.filter(e => !isEqual(e.pluginUri, pluginUri)), undefined);
		return true;
	}

	isMarketplaceTrusted(ref: IMarketplaceReference): boolean {
		const allowlist = this._getStrictMarketplaces();
		if (allowlist !== undefined) {
			return isMarketplaceReferenceAllowed(allowlist, ref);
		}
		return this._trustedMarketplacesStore.get().includes(ref.canonicalId);
	}

	isStrictMarketplacePolicyActive(): boolean {
		return this._getStrictMarketplaces() !== undefined;
	}

	private _getStrictMarketplaces() {
		const value = this._managedSettingsService.getManagedSettingValue(COPILOT_STRICT_MARKETPLACES_KEY);
		if (typeof value !== 'string') {
			return undefined;
		}
		try {
			return getStrictKnownMarketplaces(JSON.parse(value));
		} catch (error) {
			this._logService.warn('Invalid managed strictKnownMarketplaces JSON', error);
			return undefined;
		}
	}

	isMarketplaceAutoUpdateEnabled(ref: IMarketplaceReference): boolean {
		const { extraValues } = readConfiguredMarketplaces(this._configurationService);
		const managedRef = parseMarketplaceReferences(extraValues).find(candidate => candidate.canonicalId === ref.canonicalId);
		return managedRef?.autoUpdate ?? this._extensionsWorkbenchService.getAutoUpdateValue() !== 'off';
	}

	private _isMarketplaceAllowedByStrictPolicy(ref: IMarketplaceReference): boolean {
		return !this.isStrictMarketplacePolicyActive() || this.isMarketplaceTrusted(ref);
	}

	// --- Plugin metadata hydration -----------------------------------------------

	/**
	 * Hydrates installed entries from marketplace metadata. Entries written
	 * by current builds include the marketplace plugin name, which is enough
	 * to re-read the full plugin descriptor from the marketplace source. Old
	 * entries without a name fall back to matching by install URI. Entries
	 * that came from a single-plugin repository have no marketplace index to
	 * look up at all and are recovered from the manifest in their install
	 * directory.
	 *
	 * After hydration completes the installed-plugins store is "touched" so
	 * that the derived {@link installedPlugins} observable re-evaluates with
	 * the newly available metadata.
	 */
	private async _hydratePluginMetadata(entries: readonly IStoredInstalledPlugin[]): Promise<void> {
		let hydrated = 0;

		for (const entry of entries) {
			const key = entry.pluginUri.toString();
			if (this._pluginMetadata.has(key)) {
				continue;
			}

			const reference = parseMarketplaceReference(entry.marketplace);
			if (!reference) {
				this._logService.debug(`[PluginMarketplaceService] Cannot parse marketplace reference '${entry.marketplace}' for ${key}`);
				continue;
			}

			try {
				const plugins = await this._readPluginsForInstalledEntry(reference, CancellationToken.None);
				// A marketplace that resolves but no longer lists the entry (a renamed or
				// removed plugin) must not fall back: marketplace plugin directories
				// usually hold a manifest too, and reading it would reclassify the entry
				// as a direct source rooted at the marketplace repository, sending later
				// updates to the wrong place. Only an absent marketplace index means the
				// entry came from a single-plugin repo installed via
				// `installPluginFromSource`, whose descriptor lives in the recorded
				// install directory.
				const match = plugins.length === 0
					? await this.readSinglePluginManifest(entry.pluginUri, reference)
					: plugins.find(p => entry.name ? p.name === entry.name : isEqual(this._pluginRepositoryService.getPluginInstallUri(p), entry.pluginUri));
				if (match) {
					this._pluginMetadata.set(key, match);
					hydrated++;
				}
			} catch (err) {
				this._logService.debug(`[PluginMarketplaceService] Failed to hydrate metadata for ${key}:`, err);
			}
		}

		if (hydrated > 0) {
			// Touch the store to trigger the derived observable to re-evaluate
			// now that _pluginMetadata has new entries.
			const current = this._installedPluginsStore.get();
			this._installedPluginsStore.set([...current], undefined);
		}
	}

	private async _readPluginsForInstalledEntry(reference: IMarketplaceReference, token: CancellationToken): Promise<IMarketplacePlugin[]> {
		if (reference.kind === MarketplaceReferenceKind.GitHubShorthand && reference.githubRepo) {
			return this._fetchFromGitHubRepo(reference, reference.githubRepo, token);
		}

		return this._readPluginsFromDirectory(this._pluginRepositoryService.getRepositoryUri(reference), reference, token);
	}

	/**
	 * Shared logic to parse a marketplace.json into {@link IMarketplacePlugin}
	 * objects. Used by both fetch and hydration paths.
	 */
	private _parseMarketplacePlugins(json: IMarketplaceJson, reference: IMarketplaceReference, marketplaceType: MarketplaceType, repoDir?: URI): IMarketplacePlugin[] {
		if (!json.plugins || !Array.isArray(json.plugins)) {
			return [];
		}

		return json.plugins
			.filter((p): p is { name: string; description?: string; version?: string; source?: string | IJsonPluginSource } =>
				typeof p.name === 'string' && !!p.name
			)
			.flatMap(p => {
				const sourceDescriptor = parsePluginSource(p.source, json.metadata?.pluginRoot, {
					pluginName: p.name,
					logService: this._logService,
					logPrefix: '[PluginMarketplaceService]',
				});
				if (!sourceDescriptor) {
					return [];
				}

				const source = sourceDescriptor.kind === PluginSourceKind.RelativePath ? sourceDescriptor.path : '';

				return [{
					name: p.name,
					description: p.description ?? '',
					version: p.version ?? '',
					source,
					sourceDescriptor,
					marketplace: reference.displayLabel,
					marketplaceName: typeof json.name === 'string' && json.name.trim() ? json.name.trim() : undefined,
					marketplaceReference: reference,
					marketplaceType,
					readmeUri: getMarketplaceReadmeUri(sourceDescriptor, reference, source, repoDir),
				}];
			});
	}

	trustMarketplace(ref: IMarketplaceReference): void {
		const current = this._trustedMarketplacesStore.get();
		if (!current.includes(ref.canonicalId)) {
			this._trustedMarketplacesStore.set([...current, ref.canonicalId], undefined);
		}
	}

	// --- Periodic update check ------------------------------------------------

	private _hasAutoUpdateEnabledMarketplace(): boolean {
		if (this._extensionsWorkbenchService.getAutoUpdateValue() !== 'off') {
			return true;
		}
		const { extraValues } = readConfiguredMarketplaces(this._configurationService);
		return parseMarketplaceReferences(extraValues).some(ref => ref.autoUpdate === true);
	}

	/**
	 * (Re-)schedules the next periodic update check after startup idle and
	 * whenever the auto-update config or metered connection state changes.
	 */
	private _scheduleUpdateCheck(delayOverride?: number): void {
		this._updateCheckDelayer.cancel();

		if (this._store.isDisposed
			|| this._meteredConnectionService.isConnectionMetered
			|| this._marketplacesWithUpdates.get().size > 0
			|| !this._hasAutoUpdateEnabledMarketplace()) {
			return;
		}

		const lastCheck = this._storageService.getNumber(
			PLUGIN_UPDATE_LAST_CHECK_STORAGE_KEY,
			StorageScope.APPLICATION,
			0,
		);
		const elapsed = Date.now() - lastCheck;
		const delay = delayOverride ?? Math.max(0, PLUGIN_UPDATE_CHECK_INTERVAL_MS - elapsed);

		this._updateCheckDelayer.trigger(async () => {
			this._updateCheckRunning = true;
			try {
				await this._doRunUpdateCheck();
			} finally {
				this._updateCheckRunning = false;
				if (!this._updateCheckDelayer.isTriggered()) {
					this._scheduleUpdateCheck(PLUGIN_UPDATE_CHECK_INTERVAL_MS);
				}
			}
		}, delay).catch(error => {
			if (!isCancellationError(error)) {
				onUnexpectedError(error);
			}
		});
	}

	private async _doRunUpdateCheck(): Promise<void> {
		if (this._meteredConnectionService.isConnectionMetered) {
			return;
		}

		try {
			const installed = this.installedPlugins.get();
			if (installed.length === 0) {
				return;
			}

			const seenMarketplaces = new Set<string>();
			const marketplacesWithUpdates = new Set<string>();

			for (const entry of installed) {
				const ref = entry.plugin.marketplaceReference;
				if (seenMarketplaces.has(ref.canonicalId)
					|| !this.isMarketplaceAutoUpdateEnabled(ref)
					|| !this._isMarketplaceAllowedByStrictPolicy(ref)) {
					continue;
				}
				seenMarketplaces.add(ref.canonicalId);

				try {
					const behind = await this._pluginRepositoryService.fetchRepository(ref);
					if (behind) {
						marketplacesWithUpdates.add(ref.canonicalId);
					}
				} catch (err) {
					this._logService.debug(`[PluginMarketplaceService] Update check failed for ${ref.displayLabel}:`, err);
				}
			}

			this._marketplacesWithUpdates.set(marketplacesWithUpdates, undefined);
			this._storageService.store(
				PLUGIN_UPDATE_LAST_CHECK_STORAGE_KEY,
				Date.now(),
				StorageScope.APPLICATION,
				StorageTarget.MACHINE,
			);
		} catch (err) {
			this._logService.debug('[PluginMarketplaceService] Periodic update check failed:', err);
		}
	}

	private async _fetchFromClonedRepo(reference: IMarketplaceReference, token: CancellationToken, options?: IFetchMarketplacePluginsOptions): Promise<IMarketplacePlugin[]> {
		let repoDir: URI;
		try {
			repoDir = await this._pluginRepositoryService.ensureRepository(reference, {
				refreshIfOlderThanMs: options?.refresh ? 0 : GITHUB_MARKETPLACE_CACHE_TTL_MS,
				token,
			});
		} catch (err) {
			this._logService.debug(`[PluginMarketplaceService] Failed to prepare marketplace repository ${reference.rawValue}:`, err);
			options?.onMarketplaceError?.(reference, err);
			return [];
		}

		return this._readPluginsFromDirectory(repoDir, reference, token, options);
	}

	async readPluginsFromDirectory(repoDir: URI, reference: IMarketplaceReference): Promise<IMarketplacePlugin[]> {
		return this._readPluginsFromDirectory(repoDir, reference);
	}

	async readSinglePluginManifest(repoDir: URI, reference: IMarketplaceReference): Promise<IMarketplacePlugin | undefined> {
		// Single-plugin repos are only meaningful for direct git clones —
		// there's no synthetic relative-path source to fall back on.
		if (reference.kind !== MarketplaceReferenceKind.GitHubShorthand && reference.kind !== MarketplaceReferenceKind.GitUri) {
			return undefined;
		}

		const sourceDescriptor: IPluginSourceDescriptor = reference.kind === MarketplaceReferenceKind.GitHubShorthand
			? { kind: PluginSourceKind.GitHub, repo: reference.githubRepo! }
			: { kind: PluginSourceKind.GitUrl, url: reference.cloneUrl };
		const agentManifest = await readAgentPluginManifest(repoDir, this._fileService);
		if (agentManifest) {
			return {
				name: agentManifest.name ?? reference.displayLabel,
				description: agentManifest.description ?? '',
				version: agentManifest.version ?? '',
				source: '',
				sourceDescriptor,
				marketplace: reference.displayLabel,
				marketplaceReference: reference,
				marketplaceType: MarketplaceType.OpenPlugin,
			};
		}

		for (const def of SINGLE_PLUGIN_MANIFEST_DEFINITIONS) {
			const manifestUri = joinPath(repoDir, def.path);
			let manifest: Record<string, unknown> | undefined;
			try {
				const contents = await this._fileService.readFile(manifestUri);
				const parsed = parseJSONC(contents.value.toString());
				if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
					manifest = parsed as Record<string, unknown>;
				}
			} catch {
				continue;
			}
			if (!manifest) {
				continue;
			}

			const manifestName = typeof manifest['name'] === 'string' && manifest['name'] ? manifest['name'] as string : reference.displayLabel;
			const manifestDescription = typeof manifest['description'] === 'string' ? manifest['description'] as string : '';
			const manifestVersion = typeof manifest['version'] === 'string' ? manifest['version'] as string : '';

			return {
				name: manifestName,
				description: manifestDescription,
				version: manifestVersion,
				source: '',
				sourceDescriptor,
				marketplace: reference.displayLabel,
				marketplaceReference: reference,
				marketplaceType: def.type,
			};
		}

		this._logService.debug(`[PluginMarketplaceService] No single-plugin manifest found in ${reference.rawValue}`);
		return undefined;
	}

	async isPluginDirectory(repoDir: URI): Promise<boolean> {
		if (await readAgentPluginManifest(repoDir, this._fileService)) {
			return true;
		}
		for (const def of SINGLE_PLUGIN_MANIFEST_DEFINITIONS) {
			if (await this._fileService.exists(joinPath(repoDir, def.path))) {
				return true;
			}
		}
		return false;
	}

	private async _readPluginsFromDirectory(repoDir: URI, reference: IMarketplaceReference, token?: CancellationToken, options?: IFetchMarketplacePluginsOptions): Promise<IMarketplacePlugin[]> {
		let readError: unknown;
		const plugins = await this._readPluginsFromDefinitions(reference, async (defPath) => {
			if (token?.isCancellationRequested) {
				return undefined;
			}
			const definitionUri = joinPath(repoDir, defPath);
			try {
				const contents = await this._fileService.readFile(definitionUri);
				return parseJSONC(contents.value.toString()) as IMarketplaceJson | undefined;
			} catch (error) {
				if (!(error instanceof Error && toFileOperationResult(error) === FileOperationResult.FILE_NOT_FOUND)) {
					readError = error;
				}
				return undefined;
			}
		}, repoDir);
		if (!plugins.length && readError !== undefined && !token?.isCancellationRequested) {
			options?.onMarketplaceError?.(reference, readError);
		}
		return plugins;
	}

	/**
	 * Iterates over {@link MARKETPLACE_DEFINITIONS} paths, calling
	 * {@link readJson} for each to obtain the parsed JSON. Returns the
	 * plugins from the first definition that yields a valid result.
	 */
	private async _readPluginsFromDefinitions(
		reference: IMarketplaceReference,
		readJson: (defPath: string) => Promise<IMarketplaceJson | undefined>,
		repoDir?: URI,
	): Promise<IMarketplacePlugin[]> {
		for (const def of MARKETPLACE_DEFINITIONS) {
			const json = await readJson(def.path);
			if (!json?.plugins || !Array.isArray(json.plugins)) {
				continue;
			}
			return this._parseMarketplacePlugins(json, reference, def.type, repoDir);
		}

		this._logService.debug(`[PluginMarketplaceService] No marketplace.json found in ${reference.rawValue}`);
		return [];
	}
}

function normalizeMarketplacePath(value: string): string {
	let normalized = value.trim().replace(/\\/g, '/');
	normalized = normalized.replace(/^\.?\/+/, '').replace(/\/+$/g, '');
	return normalized;
}

/**
 * Resolve plugin source from marketplace metadata.
 * - If pluginRoot exists, plugin source is resolved relative to it.
 * - If source already includes pluginRoot, it's preserved.
 * Validation of whether the final path is allowed is performed by the install service.
 */
function resolvePluginSource(pluginRoot: string | undefined, source: string): string | undefined {
	const normalizedRoot = pluginRoot ? normalizeMarketplacePath(pluginRoot) : '';
	const normalizedSource = normalizeMarketplacePath(source);
	const repoRoot = URI.file('/');
	const pluginRootUri = normalizedRoot ? normalizePath(joinPath(repoRoot, normalizedRoot)) : repoRoot;

	if (normalizedRoot && (normalizedSource === normalizedRoot || normalizedSource.startsWith(`${normalizedRoot}/`))) {
		return normalizedSource;
	}

	const resolvedUri = normalizePath(joinPath(pluginRootUri, normalizedSource));
	return relativePath(repoRoot, resolvedUri) ?? undefined;
}

/**
 * Parse a raw `source` field from marketplace.json into a structured
 * {@link IPluginSourceDescriptor}. Accepts either a relative-path string
 * or a JSON object with a `source` discriminant indicating the kind.
 */
export function parsePluginSource(
	rawSource: string | IJsonPluginSource | undefined,
	pluginRoot: string | undefined,
	logContext: { pluginName: string; logService: ILogService; logPrefix: string },
): IPluginSourceDescriptor | undefined {
	if (rawSource === undefined || rawSource === null) {
		// Treat missing source the same as empty string → pluginRoot or repo root.
		const resolved = resolvePluginSource(pluginRoot, '');
		if (resolved === undefined) {
			return undefined;
		}
		return { kind: PluginSourceKind.RelativePath, path: resolved };
	}

	// String source → legacy relative-path behaviour.
	if (typeof rawSource === 'string') {
		const resolved = resolvePluginSource(pluginRoot, rawSource);
		if (resolved === undefined) {
			return undefined;
		}
		return { kind: PluginSourceKind.RelativePath, path: resolved };
	}

	// Object source → discriminated by `rawSource.source`.
	if (typeof rawSource !== 'object' || typeof rawSource.source !== 'string') {
		logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': source object is missing a 'source' discriminant`);
		return undefined;
	}

	switch (rawSource.source) {
		case 'github': {
			if (typeof rawSource.repo !== 'string' || !rawSource.repo) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': github source is missing required 'repo' field`);
				return undefined;
			}
			if (!isValidGitHubRepo(rawSource.repo)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': github source repo must be in 'owner/repo' format`);
				return undefined;
			}
			if (!isOptionalString(rawSource.ref)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': github source 'ref' must be a string when provided`);
				return undefined;
			}
			if (!isOptionalGitSha(rawSource.sha)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': github source 'sha' must be a full 40-character commit hash when provided`);
				return undefined;
			}
			if (!isOptionalString(rawSource.path)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': github source 'path' must be a string when provided`);
				return undefined;
			}
			try {
				gitRevisionCacheSuffix(rawSource.ref, rawSource.sha);
			} catch (error) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': github source revision contains invalid path segments`, error);
				return undefined;
			}
			return {
				kind: PluginSourceKind.GitHub,
				repo: rawSource.repo,
				ref: rawSource.ref,
				sha: rawSource.sha,
				path: rawSource.path,
			};
		}
		case 'url':
		case 'git-subdir': {
			if (typeof rawSource.url !== 'string' || !rawSource.url) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': ${rawSource.source} source is missing required 'url' field`);
				return undefined;
			}
			if (rawSource.source === 'url' && !rawSource.url.toLowerCase().endsWith('.git')) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': url source must end with '.git'`);
				return undefined;
			}
			if (!isOptionalString(rawSource.ref)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': ${rawSource.source} source 'ref' must be a string when provided`);
				return undefined;
			}
			if (!isOptionalGitSha(rawSource.sha)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': ${rawSource.source} source 'sha' must be a full 40-character commit hash when provided`);
				return undefined;
			}
			if (rawSource.source === 'git-subdir') {
				if (typeof rawSource.path !== 'string' || !rawSource.path) {
					logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': git-subdir source is missing required 'path' field`);
					return undefined;
				}
			} else if (!isOptionalString(rawSource.path)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': url source 'path' must be a string when provided`);
				return undefined;
			}
			try {
				getGitUrlCacheSegments(rawSource.url);
				gitRevisionCacheSuffix(rawSource.ref, rawSource.sha);
			} catch (error) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': ${rawSource.source} source URL or revision contains invalid path segments`, error);
				return undefined;
			}
			return {
				kind: PluginSourceKind.GitUrl,
				url: rawSource.url,
				ref: rawSource.ref,
				sha: rawSource.sha,
				path: rawSource.path,
			};
		}
		case 'npm': {
			if (typeof rawSource.package !== 'string' || !rawSource.package) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': npm source is missing required 'package' field`);
				return undefined;
			}
			if (!isOptionalString(rawSource.version) || !isOptionalString(rawSource.registry)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': npm source 'version' and 'registry' must be strings when provided`);
				return undefined;
			}
			return {
				kind: PluginSourceKind.Npm,
				package: rawSource.package,
				version: rawSource.version,
				registry: rawSource.registry,
			};
		}
		case 'pip': {
			if (typeof rawSource.package !== 'string' || !rawSource.package) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': pip source is missing required 'package' field`);
				return undefined;
			}
			if (!isOptionalString(rawSource.version) || !isOptionalString(rawSource.registry)) {
				logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': pip source 'version' and 'registry' must be strings when provided`);
				return undefined;
			}
			return {
				kind: PluginSourceKind.Pip,
				package: rawSource.package,
				version: rawSource.version,
				registry: rawSource.registry,
			};
		}
		default:
			logContext.logService.warn(`${logContext.logPrefix} Skipping plugin '${logContext.pluginName}': unknown source kind '${rawSource.source}'`);
			return undefined;
	}
}

function isOptionalString(value: unknown): value is string | undefined {
	return value === undefined || typeof value === 'string';
}

function isOptionalGitSha(value: unknown): value is string | undefined {
	return value === undefined || (typeof value === 'string' && /^[0-9a-fA-F]{40}$/.test(value));
}

function isValidGitHubRepo(repo: string): boolean {
	return /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo) && !!parseMarketplaceReference(repo);
}

/**
 * Returns a human-readable label for a plugin source descriptor,
 * suitable for error messages and UI display.
 */
export function getPluginSourceLabel(descriptor: IPluginSourceDescriptor): string {
	switch (descriptor.kind) {
		case PluginSourceKind.RelativePath:
			return descriptor.path || '.';
		case PluginSourceKind.GitHub:
			return descriptor.path ? `${descriptor.repo}/${descriptor.path}` : descriptor.repo;
		case PluginSourceKind.GitUrl:
			return descriptor.path ? `${descriptor.url}/${descriptor.path}` : descriptor.url;
		case PluginSourceKind.Npm:
			return descriptor.version ? `${descriptor.package}@${descriptor.version}` : descriptor.package;
		case PluginSourceKind.Pip:
			return descriptor.version ? `${descriptor.package}==${descriptor.version}` : descriptor.package;
	}
}

/**
 * Returns `true` when the marketplace source descriptor differs from the
 * installed one — meaning an update should be performed.
 */
export function hasSourceChanged(installed: IPluginSourceDescriptor, marketplace: IPluginSourceDescriptor): boolean {
	if (installed.kind !== marketplace.kind) {
		return true;
	}

	switch (installed.kind) {
		case PluginSourceKind.GitHub:
			return installed.ref !== (marketplace as typeof installed).ref
				|| installed.sha !== (marketplace as typeof installed).sha
				|| installed.path !== (marketplace as typeof installed).path;
		case PluginSourceKind.GitUrl:
			return installed.ref !== (marketplace as typeof installed).ref
				|| installed.sha !== (marketplace as typeof installed).sha
				|| installed.path !== (marketplace as typeof installed).path;
		case PluginSourceKind.Npm:
			return installed.version !== (marketplace as typeof installed).version;
		case PluginSourceKind.Pip:
			return installed.version !== (marketplace as typeof installed).version;
		default:
			return false;
	}
}

function getMarketplaceReadmeUri(sourceDescriptor: IPluginSourceDescriptor, reference: IMarketplaceReference, source: string, repoDir?: URI): URI | undefined {
	if (sourceDescriptor.kind === PluginSourceKind.GitHub) {
		const ref = sourceDescriptor.sha ?? sourceDescriptor.ref ?? 'main';
		const normalizedPath = sourceDescriptor.path?.trim().replace(/^\.?\/+|\/+$/g, '');
		const readmePath = normalizedPath ? `${normalizedPath}/README.md` : 'README.md';
		return URI.parse(`https://github.com/${sourceDescriptor.repo}/blob/${ref}/${readmePath}`);
	}

	if (sourceDescriptor.kind === PluginSourceKind.GitUrl && sourceDescriptor.url.startsWith('https://github.com/')) {
		const repo = sourceDescriptor.url.replace(/^https:\/\/github\.com\//, '').replace(/\.git$/, '');
		const ref = sourceDescriptor.sha ?? sourceDescriptor.ref ?? 'main';
		const normalizedPath = sourceDescriptor.path?.trim().replace(/^\.?\/+|\/+$/g, '');
		const readmePath = normalizedPath ? `${normalizedPath}/README.md` : 'README.md';
		return URI.parse(`https://github.com/${repo}/blob/${ref}/${readmePath}`);
	}

	if (repoDir) {
		return getMarketplaceReadmeFileUri(repoDir, source);
	}

	if (!reference.githubRepo) {
		return undefined;
	}

	const normalizedSource = source.trim().replace(/^\.?\/+|\/+$/g, '');
	const readmePath = normalizedSource ? `${normalizedSource}/README.md` : 'README.md';
	const ref = reference.ref ?? 'main';
	return URI.parse(`https://github.com/${reference.githubRepo}/blob/${ref}/${readmePath}`);
}

function getMarketplaceReadmeFileUri(repoDir: URI, source: string): URI {
	const normalizedSource = source.trim().replace(/^\.?\/+|\/+$/g, '');
	return normalizedSource ? joinPath(repoDir, normalizedSource, 'README.md') : joinPath(repoDir, 'README.md');
}
