import { VSBuffer } from '../../../base/common/buffer.js';
import { Sequencer } from '../../../base/common/async.js';
import { StringSHA1 } from '../../../base/common/hash.js';
import { Disposable } from '../../../base/common/lifecycle.js';
import { LRUCache, ResourceMap } from '../../../base/common/map.js';
import { MarshalledId } from '../../../base/common/marshallingIds.js';
import { IProductConfiguration } from '../../../base/common/product.js';
import { isEqual, isEqualOrParent, joinPath } from '../../../base/common/resources.js';
import { isUriComponents, URI, UriComponents } from '../../../base/common/uri.js';
import { FileOperationResult, IFileService, IFileStatWithMetadata, toFileOperationResult } from '../../files/common/files.js';
import { ILogService } from '../../log/common/log.js';
import { AHP_CANVAS_SCHEME } from './canvasUri.js';

export type AhpLogDirection = 'c2s' | 's2c';

interface IAhpLogMeta {
	readonly ts: string;
	readonly dir: AhpLogDirection;
	readonly connectionId: string;
	readonly transport: string;
	readonly byteLength?: number;
	readonly droppedEntries?: number;
	/** Set when oversized string values in the entry were elided (see {@link stringifyAhpLogEntryTruncated}). */
	truncated?: boolean;
}

export interface IAhpJsonlLoggerOptions {
	readonly logsHome: URI;
	/** Stable identity shared by every transport connection to the same logical host. */
	readonly logId: string;
	readonly connectionId: string;
	readonly transport: string;
	readonly maxFileSizeBytes?: number;
	readonly maxFiles?: number;
	readonly retention?: AhpJsonlLogRetention;
	readonly maxPendingBytes?: number;
	/** Cumulative budget shared by this process's loggers for logsHome, fixed by its first logger. */
	readonly maxTotalSizeBytes?: number;
	/** Checked before serializing each message so host capture can follow live configuration. */
	readonly isEnabled?: () => boolean;
}

export const AgentHostAhpJsonlLoggingEnvVar = 'VSCODE_AGENT_HOST_AHP_JSONL_LOGGING';

export function isAhpJsonlLoggingEnabled(quality: IProductConfiguration['quality'], override?: string): boolean {
	return override === undefined ? quality === 'insider' : override === 'true';
}

const AHP_LOG_DIR = 'ahp';
const AHP_LOG_FILE_PREFIX = 'ahp';
const AHP_LOG_FILE_EXTENSION = '.jsonl';
const DEFAULT_MAX_FILE_SIZE_BYTES = 75 * 1024 * 1024;
const DEFAULT_MAX_FILES = 5;
const DEFAULT_MAX_PENDING_BYTES = 4 * 1024 * 1024;
const DEFAULT_MAX_TOTAL_SIZE_BYTES = 500 * 1024 * 1024;
// Cap the size of any single coalesced writeFile to avoid producing huge
// concatenated VSBuffers (which would just create the GC pressure we're
// trying to avoid). 1 MiB strikes a balance between amortizing IPC overhead
// and keeping per-write allocations modest.
const MAX_BATCH_BYTES = 1024 * 1024;

// A single AHP protocol message can be enormous (e.g. a `resourceRead` carrying
// a base64-encoded file, or an `action` carrying a full session snapshot). We
// don't want to write hundreds of MB on a single JSONL line — it bloats the log
// directory and, more importantly, building/holding that line creates exactly
// the GC pressure these logs are meant to help diagnose. When a serialized
// entry exceeds this size we re-serialize it with oversized string values
// elided so the line stays well-formed JSONL.
const MAX_LOG_LINE_LENGTH = 1024 * 1024;
// When trimming an oversized entry, individual string values are capped to this
// length. Generous enough to keep messages useful for debugging.
const MAX_LOGGED_STRING_LENGTH = 16 * 1024;
const REDACTED_CANVAS_SOURCE = '<redacted canvas source>';

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null;
}

/** Serializes writes and bounds a logical host's history across connection generations. */
export class AhpJsonlLogRetention {
	private readonly _writes = new Sequencer();

	constructor(
		private readonly _options: { readonly logsHome: URI; readonly logId: string; readonly maxFiles: number; readonly maxSizeBytes: number },
		@IFileService private readonly _fileService: IFileService,
		@ILogService private readonly _logService: ILogService,
	) { }

	run(write: () => Promise<void>, currentResource: () => URI): Promise<void> {
		return this._writes.queue(async () => {
			await write();
			const current = currentResource();
			const directory = await this._fileService.resolve(joinPath(this._options.logsHome, AHP_LOG_DIR), { resolveMetadata: true });
			const files = (directory.children ?? [])
				.filter(file => file.isFile && !file.isSymbolicLink && isAhpLogFileFor(this._options.logId, file.name))
				.sort((a, b) => Number(isEqual(b.resource, current)) - Number(isEqual(a.resource, current))
					|| (b.mtime ?? 0) - (a.mtime ?? 0) || b.name.localeCompare(a.name));
			let count = files.length;
			let size = files.reduce((sum, file) => sum + (file.size ?? 0), 0);
			for (const file of files.reverse()) {
				if (count <= this._options.maxFiles && size <= this._options.maxSizeBytes) {
					break;
				}
				try {
					await this._fileService.del(file.resource);
					count--;
					size -= file.size ?? 0;
				} catch (error) {
					this._logService.warn('[AHPLog] Failed to remove retained transport log', file.resource.toString(), error);
				}
			}
		});
	}
}

export class AhpJsonlLogger extends Disposable {

	// Process-lifetime accounting must outlive disposed connections and their rotated files.
	private static readonly _budgets = new ResourceMap<{ remainingBytes: number; exhausted: boolean }>();
	private readonly _budget: { remainingBytes: number; exhausted: boolean };
	private readonly _logReadRequests = new LRUCache<string | number, boolean>(1024);
	private readonly _directory: URI;
	private readonly _baseName: string;
	private readonly _maxFileSizeBytes: number;
	private readonly _maxFiles: number;
	private readonly _maxPendingBytes: number;
	private _currentFile: URI;
	private _currentSize = 0;
	private _segment = 0;
	private _queue = Promise.resolve();
	private _pending: VSBuffer[] = [];
	private _pendingBytes = 0;
	private readonly _droppedEntries: Record<AhpLogDirection, number> = { c2s: 0, s2c: 0 };
	private _drainScheduled = false;
	private _folderCreated: Promise<IFileStatWithMetadata> | undefined;

	constructor(
		private readonly _options: IAhpJsonlLoggerOptions,
		@IFileService private readonly _fileService: IFileService,
		@ILogService private readonly _logService: ILogService,
	) {
		super();
		let budget = AhpJsonlLogger._budgets.get(this._options.logsHome);
		if (!budget) {
			budget = { remainingBytes: this._options.maxTotalSizeBytes ?? DEFAULT_MAX_TOTAL_SIZE_BYTES, exhausted: false };
			AhpJsonlLogger._budgets.set(this._options.logsHome, budget);
		}
		this._budget = budget;
		this._directory = joinPath(this._options.logsHome, AHP_LOG_DIR);
		// Truncate connectionId to avoid filesystem filename length limits (e.g. 255 on ext4/APFS)
		const safeConnectionId = sanitizeFilePart(this._options.connectionId).slice(0, 64);
		this._baseName = `${getAhpLogFilePrefix(this._options.logId)}${toFileTimestamp(new Date())}-${safeConnectionId}${AHP_LOG_FILE_EXTENSION}`;
		this._maxFileSizeBytes = this._options.maxFileSizeBytes ?? DEFAULT_MAX_FILE_SIZE_BYTES;
		this._maxFiles = this._options.maxFiles ?? DEFAULT_MAX_FILES;
		this._maxPendingBytes = this._options.maxPendingBytes ?? DEFAULT_MAX_PENDING_BYTES;
		this._currentFile = joinPath(this._directory, this._baseName);
	}

	get resource(): URI {
		return this._currentFile;
	}

	log(message: object, dir: AhpLogDirection, byteLength?: number): void {
		if (this._budget.exhausted || this._options.isEnabled?.() === false || this._isLogInspection(message, dir)) {
			return;
		}
		if (this._pendingBytes >= this._maxPendingBytes) {
			this._droppedEntries[dir]++;
			return;
		}
		const meta: IAhpLogMeta = {
			ts: new Date().toISOString(),
			dir,
			connectionId: this._options.connectionId,
			transport: this._options.transport,
			...(typeof byteLength === 'number' ? { byteLength } : {}),
		};
		const entry = { ...message, _ahpLog: meta };
		// Fast path: serialize once. The vast majority of messages are small, so
		// we only pay a single stringify and use its length to decide whether the
		// rare oversized-message path below is needed.
		let body = stringifyAhpLogEntry(entry);
		if (body.length > MAX_LOG_LINE_LENGTH) {
			// Slow path (rare): a single message carried very large payloads. Walk
			// the object via a replacer that elides long string values, keeping the
			// line valid JSONL instead of writing/holding the full multi-MB payload.
			meta.truncated = true;
			body = stringifyAhpLogEntryTruncated(entry, MAX_LOGGED_STRING_LENGTH);
		}
		const line = `${body}\n`;
		this._enqueue(VSBuffer.fromString(line));
	}

	/** Avoids recording log contents or generating new log writes in response to watching those logs. */
	private _isLogInspection(message: object, dir: AhpLogDirection): boolean {
		if (!isRecord(message)) {
			return false;
		}
		const id = message.id;
		if (dir === 's2c' && message.method === undefined && (typeof id === 'number' || typeof id === 'string') && this._logReadRequests.delete(id)) {
			return true;
		}
		const params = message.params;
		if (!isRecord(params)) {
			return false;
		}
		if (dir === 'c2s' && (message.method === 'resourceRead' || message.method === 'resourceResolve' || message.method === 'resourceList' || message.method === 'resourceRequest' || message.method === 'createResourceWatch')
			&& this._isLogResource(params.uri)) {
			if (typeof id === 'number' || typeof id === 'string') {
				this._logReadRequests.set(id, true);
			}
			return true;
		}
		const action = params.action;
		return message.method === 'action' && isRecord(action) && action.type === 'resourceWatch/changed'
			&& isRecord(action.changes) && Array.isArray(action.changes.items) && action.changes.items.length > 0
			&& action.changes.items.every(change => isRecord(change) && this._isLogResource(change.uri));
	}

	private _isLogResource(value: unknown): boolean {
		if (URI.isUri(value)) {
			return isEqualOrParent(value, this._directory);
		}
		if (typeof value !== 'string') {
			return false;
		}
		try {
			return isEqualOrParent(URI.parse(value, true), this._directory);
		} catch {
			return false;
		}
	}

	private _enqueue(buffer: VSBuffer): void {
		if (this._budget.exhausted) {
			return;
		}
		if (buffer.byteLength > this._budget.remainingBytes) {
			this._budget.exhausted = true;
			this._logService.warn('[AHPLog] Transport logging stopped: shared process byte budget exhausted', this._options.logsHome.toString());
			return;
		}
		this._budget.remainingBytes -= buffer.byteLength;
		this._pending.push(buffer);
		this._pendingBytes += buffer.byteLength;
		this._scheduleDrain();
	}

	async flush(): Promise<void> {
		let queue: Promise<void>;
		do {
			queue = this._queue;
			await queue;
		} while (queue !== this._queue);
	}

	private _scheduleDrain(): void {
		if (this._drainScheduled) {
			return;
		}
		this._drainScheduled = true;
		this._queue = this._queue.then(() => this._options.retention
			? this._options.retention.run(() => this._drainPending(), () => this._currentFile)
			: this._drainPending()).catch(error => {
				this._logService.error('[AHPLog] Failed to write transport log', error);
			});
	}

	private async _drainPending(): Promise<void> {
		// Clear the scheduled flag before snapshotting _pending so that any log()
		// calls happening during the awaits below will schedule a fresh drain.
		this._drainScheduled = false;
		if (this._pending.length === 0) {
			return;
		}
		const buffers = this._pending;
		this._pending = [];
		const buffersSize = buffers.reduce((total, buffer) => total + buffer.byteLength, 0);
		try {
			await this._writeBuffers(buffers);
		} finally {
			this._pendingBytes -= buffersSize;
			this._enqueueDroppedEntries();
		}
	}

	private async _writeBuffers(buffers: readonly VSBuffer[]): Promise<void> {
		// Create folder once and memoize to avoid repeated filesystem calls
		if (!this._folderCreated) {
			this._folderCreated = this._fileService.createFolder(this._directory);
		}
		await this._folderCreated;
		if (this._currentSize === 0 || this._options.retention) {
			this._currentSize = await this._getFileSize(this._currentFile);
		}

		// Coalesce buffers into chunks, respecting both file-rotation size and the
		// per-write batch cap. Rotation is checked per-entry to preserve the
		// invariant that we don't exceed maxFileSizeBytes once a file has data.
		let chunk: VSBuffer[] = [];
		let chunkSize = 0;
		const flushChunk = async () => {
			if (chunk.length === 0) {
				return;
			}
			const combined = chunk.length === 1 ? chunk[0] : VSBuffer.concat(chunk, chunkSize);
			await this._fileService.writeFile(this._currentFile, combined, { append: true });
			this._currentSize += combined.byteLength;
			chunk = [];
			chunkSize = 0;
		};

		for (const buffer of buffers) {
			const totalInFile = this._currentSize + chunkSize;
			if (totalInFile > 0 && totalInFile + buffer.byteLength > this._maxFileSizeBytes) {
				await flushChunk();
				await this._rotate();
			} else if (chunkSize > 0 && chunkSize + buffer.byteLength > MAX_BATCH_BYTES) {
				// Same file but the batch is getting too large; flush early to
				// avoid creating an oversized concatenated VSBuffer.
				await flushChunk();
			}
			chunk.push(buffer);
			chunkSize += buffer.byteLength;
		}
		await flushChunk();
	}

	private _enqueueDroppedEntries(): void {
		if (this._budget.exhausted) {
			return;
		}
		for (const dir of ['c2s', 's2c'] as const) {
			const droppedEntries = this._droppedEntries[dir];
			if (droppedEntries === 0 || this._pendingBytes >= this._maxPendingBytes) {
				continue;
			}
			this._droppedEntries[dir] = 0;
			const entry = {
				_ahpLog: {
					ts: new Date().toISOString(),
					dir,
					connectionId: this._options.connectionId,
					transport: this._options.transport,
					droppedEntries,
				} satisfies IAhpLogMeta,
			};
			this._enqueue(VSBuffer.fromString(`${stringifyAhpLogEntry(entry)}\n`));
		}
	}

	private async _rotate(): Promise<void> {
		this._segment++;
		const oldSegment = this._segment - this._maxFiles;
		if (oldSegment >= 0) {
			await this._fileService.del(this._resourceForSegment(oldSegment)).catch(error => {
				this._logService.trace('[AHPLog] Failed to delete old transport log', error);
			});
		}
		this._currentFile = this._resourceForSegment(this._segment);
		this._currentSize = await this._getFileSize(this._currentFile);
	}

	private _resourceForSegment(segment: number): URI {
		if (segment === 0) {
			return joinPath(this._directory, this._baseName);
		}
		const currentBaseName = this._baseName.slice(0, -AHP_LOG_FILE_EXTENSION.length);
		return joinPath(this._directory, `${currentBaseName}.${segment}${AHP_LOG_FILE_EXTENSION}`);
	}

	private async _getFileSize(resource: URI): Promise<number> {
		try {
			return (await this._fileService.resolve(resource)).size ?? 0;
		} catch (error) {
			if (this._options.retention && (!(error instanceof Error) || toFileOperationResult(error) !== FileOperationResult.FILE_NOT_FOUND)) {
				throw error;
			}
			return 0;
		}
	}
}

export function getAhpLogByteLength(text: string): number {
	return VSBuffer.fromString(text).byteLength;
}

/** Tests whether a JSONL filename belongs to the given logical Agent Host connection. */
export function isAhpLogFileFor(logId: string, name: string): boolean {
	return name.startsWith(getAhpLogFilePrefix(logId)) && name.endsWith(AHP_LOG_FILE_EXTENSION);
}

export function stringifyAhpLogEntry(value: unknown): string {
	return JSON.stringify(value, _ahpReplacer);
}

/**
 * Like {@link stringifyAhpLogEntry} but additionally elides any string value
 * longer than {@param maxStringLength}, replacing the overflow with a short
 * marker. The result is still well-formed JSON, so the log remains valid JSONL.
 * Only used for the rare oversized entry, so the extra per-value work is fine.
 */
function stringifyAhpLogEntryTruncated(value: unknown, maxStringLength: number): string {
	return JSON.stringify(value, function (this: unknown, key: string, val: unknown): unknown {
		const revived = _ahpReplacer.call(this, key, val);
		if (typeof revived === 'string' && revived.length > maxStringLength) {
			return `${revived.slice(0, maxStringLength)}…[${revived.length - maxStringLength} more chars elided]`;
		}
		return revived;
	});
}

/**
 * JSON.stringify replacer that converts URI values to their canonical string
 * form. `URI.prototype.toJSON()` runs before this replacer is invoked and
 * produces a {@link UriComponents}-shaped object stamped with
 * `$mid: MarshalledId.Uri`, which we detect here to round-trip back through
 * {@link URI.revive}. This avoids the expensive deep-clone tree walk that
 * would otherwise be required to find every URI in a message payload.
 */
function _ahpReplacer(this: unknown, _key: string, value: unknown): unknown {
	if (isRecord(value)) {
		if ((value.method === 'channel/frame' || value.method === 'tcp/data') && isRecord(value.params)) {
			return { ...value, params: { ...value.params, data: '<redacted channel payload>' } };
		}
		if (value.method === 'authenticate' && isRecord(value.params) && value.params.token !== undefined
			&& value.params.token !== '<redacted>' && value.params.token !== '[REDACTED]') {
			return { ...value, params: { ...value.params, token: '<redacted>' } };
		}
		if (value.type === 'canvas/stateChanged' && isRecord(value.canvas) && value.canvas.url !== undefined) {
			return { ...value, canvas: { ...value.canvas, url: REDACTED_CANVAS_SOURCE } };
		}
		const isCanvasResource = typeof value.resource === 'string'
			? value.resource.toLowerCase().startsWith(`${AHP_CANVAS_SCHEME}:`)
			: URI.isUri(value.resource) && value.resource.scheme === AHP_CANVAS_SCHEME;
		if (isCanvasResource && isRecord(value.state) && value.state.url !== undefined) {
			return { ...value, state: { ...value.state, url: REDACTED_CANVAS_SOURCE } };
		}
	}
	if (
		value
		&& typeof value === 'object'
		&& (value as { $mid?: number }).$mid === MarshalledId.Uri
		&& isUriComponents(value)
	) {
		return URI.revive(value as UriComponents).toString();
	}
	return value;
}

function toFileTimestamp(date: Date): string {
	return date.toISOString().replace(/[:.]/g, '-');
}

function getAhpLogFilePrefix(logId: string): string {
	const hash = new StringSHA1();
	hash.update(logId);
	return `${AHP_LOG_FILE_PREFIX}-${hash.digest()}-`;
}

function sanitizeFilePart(value: string): string {
	return value.replace(/[\\/:\*\?"<>\|\s]+/g, '-').replace(/^-+|-+$/g, '') || 'connection';
}
